  const regionWidth = workBounds.right - workBounds.left + 1;
  const regionHeight = workBounds.bottom - workBounds.top + 1;
  const next = layer.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
