export const DEFAULT_TILE_SIZE = 256;
export const MAX_TILE_SIZE = 1024;

export interface PixelRegion {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface PixelPatch extends PixelRegion {
  readonly pixels: Uint8ClampedArray;
}

export interface PixelTile extends PixelRegion {
  readonly key: number;
  readonly column: number;
  readonly row: number;
  readonly pixels: Uint8ClampedArray;
}

export interface PixelSource {
  readonly width: number;
  readonly height: number;
  readonly allocatedByteLength: number;
  pixelChunks(region?: PixelRegion): Iterable<PixelPatch>;
  read(region: PixelRegion): Uint8ClampedArray;
  toContiguous(): Uint8ClampedArray;
}

export interface PixelWriteResult {
  readonly store: TiledPixelStore;
  readonly dirtyRegion: PixelRegion | null;
  readonly changedTileKeys: readonly number[];
}

export interface TiledPixelStoreSnapshot {
  readonly schemaVersion: 1;
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly tiles: readonly {
    readonly column: number;
    readonly row: number;
    readonly pixels: Uint8ClampedArray;
  }[];
}

export interface TiledPixelStoreDelta {
  readonly tiles: TiledPixelStoreSnapshot['tiles'];
  readonly removedTileKeys: readonly number[];
}

export interface CoveragePatch extends PixelRegion {
  readonly coverage: Uint8ClampedArray;
}

export interface CoverageSource {
  readonly width: number;
  readonly height: number;
  readonly allocatedByteLength: number;
  coverageChunks(region?: PixelRegion): Iterable<CoveragePatch>;
  read(region: PixelRegion): Uint8ClampedArray;
  toContiguous(): Uint8ClampedArray;
}

export class ContiguousCoverageSource implements CoverageSource {
  readonly allocatedByteLength: number;
  constructor(
    readonly width: number,
    readonly height: number,
    readonly coverage: Uint8ClampedArray,
  ) {
    validateDimensions(width, height, DEFAULT_TILE_SIZE);
    if (coverage.length !== width * height)
      throw new RangeError('Coverage buffer length does not match its dimensions');
    this.allocatedByteLength = coverage.byteLength;
  }
  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
      const start = y * this.width + clipped.x;
      const destination = (y - region.y) * region.width + clipped.x - region.x;
      output.set(this.coverage.subarray(start, start + clipped.width), destination);
    }
    return output;
  }
  *coverageChunks(region?: PixelRegion): IterableIterator<CoveragePatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    yield { ...requested, coverage: this.read(requested) };
  }
  toContiguous(): Uint8ClampedArray {
    return new Uint8ClampedArray(this.coverage);
  }
}

export interface CoverageTile extends PixelRegion {
  readonly key: number;
  readonly column: number;
  readonly row: number;
  readonly coverage: Uint8ClampedArray;
}

export interface CoverageWriteResult {
  readonly store: TiledCoverageStore;
  readonly dirtyRegion: PixelRegion | null;
  readonly changedTileKeys: readonly number[];
}

export interface TiledCoverageStoreSnapshot {
  readonly schemaVersion: 2;
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly defaultCoverage: number;
  readonly tiles: readonly {
    readonly column: number;
    readonly row: number;
    readonly coverage: Uint8ClampedArray;
  }[];
}

export interface TiledCoverageStoreDelta {
  readonly tiles: TiledCoverageStoreSnapshot['tiles'];
  readonly removedTileKeys: readonly number[];
}

export class DirtyRegionAccumulator {
  readonly #bounds: PixelRegion;
  readonly #maxRegions: number;
  #regions: PixelRegion[] = [];

  constructor(width: number, height: number, maxRegions = 32) {
    positiveInteger(width, 'Dirty-region width');
    positiveInteger(height, 'Dirty-region height');
    positiveInteger(maxRegions, 'Dirty-region limit');
    this.#bounds = { x: 0, y: 0, width, height };
    this.#maxRegions = maxRegions;
  }

  get size(): number {
    return this.#regions.length;
  }

  add(region: PixelRegion): void {
    const clipped = intersectRegions(region, this.#bounds);
    if (!clipped) return;
    let candidate = clipped;
    const remaining = [...this.#regions];
    for (let index = 0; index < remaining.length; ) {
      const current = remaining[index];
      if (regionsTouch(candidate, current)) {
        candidate = unionRegions(candidate, current) ?? candidate;
        remaining.splice(index, 1);
        index = 0;
      } else {
        index += 1;
      }
    }
    remaining.push(candidate);
    this.#regions = remaining;
    if (this.#regions.length > this.#maxRegions) {
      this.#regions = [
        this.#regions.reduce<PixelRegion | null>(
          (combined, item) => unionRegions(combined, item),
          null,
        ) ?? clipped,
      ];
    }
  }

  invalidateAll(): void {
    this.#regions = [{ ...this.#bounds }];
  }

  peek(): readonly PixelRegion[] {
    return this.#regions.map((region) => ({ ...region }));
  }

  consume(): readonly PixelRegion[] {
    const regions = this.peek();
    this.#regions = [];
    return regions;
  }
}

function positiveInteger(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value <= 0) throw new RangeError(`${label} must be positive`);
}

function integer(value: number, label: string): void {
  if (!Number.isSafeInteger(value)) throw new RangeError(`${label} must be an integer`);
}

function snapshotInteger(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value)) {
    throw new RangeError(`${label} must be an integer`);
  }
  return value;
}

function tileKey(column: number, row: number, columnCount: number): number {
  return row * columnCount + column;
}

function tileIsTransparent(pixels: Uint8ClampedArray): boolean {
  return pixels.every((value) => value === 0);
}

function tileIsUniform(values: Uint8ClampedArray, expected: number): boolean {
  for (let index = 0; index < values.length; index += 1) {
    if ((values[index] ?? 0) !== expected) return false;
  }
  return true;
}

export class TiledPixelStore {
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly columnCount: number;
  readonly rowCount: number;
  readonly #tiles: ReadonlyMap<number, Uint8ClampedArray>;

  private constructor(
    width: number,
    height: number,
    tileSize: number,
    tiles: ReadonlyMap<number, Uint8ClampedArray>,
  ) {
    this.width = width;
    this.height = height;
    this.tileSize = tileSize;
    this.columnCount = Math.ceil(width / tileSize);
    this.rowCount = Math.ceil(height / tileSize);
    this.#tiles = tiles;
  }

  static empty(width: number, height: number, tileSize = DEFAULT_TILE_SIZE): TiledPixelStore {
    validateDimensions(width, height, tileSize);
    return new TiledPixelStore(width, height, tileSize, new Map());
  }

  static fromContiguous(
    width: number,
    height: number,
    pixels: ArrayLike<number>,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledPixelStore {
    validateDimensions(width, height, tileSize);
    if (pixels.length !== width * height * 4) {
      throw new RangeError('Pixel buffer length does not match its dimensions');
    }
    const store = TiledPixelStore.empty(width, height, tileSize);
    return store.write({ x: 0, y: 0, width, height, pixels: new Uint8ClampedArray(pixels) }).store;
  }

  /** Rehydrates an owned sparse store from its worker/persistence boundary representation. */
  static fromSnapshot(value: unknown): TiledPixelStore {
    if (typeof value !== 'object' || value === null) {
      throw new TypeError('Tiled pixel snapshot must be an object');
    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1) throw new RangeError('Unsupported tiled pixel snapshot');
    const width = snapshotInteger(snapshot.width, 'Snapshot width');
    const height = snapshotInteger(snapshot.height, 'Snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Snapshot tile size');
    validateDimensions(width, height, tileSize);
    if (!Array.isArray(snapshot.tiles)) throw new TypeError('Snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key)) throw new RangeError(`Snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Snapshot tile ${String(index)} pixels must be Uint8ClampedArray`);
      }
      if (tile.pixels.length !== tileWidth * tileHeight * 4) {
        throw new RangeError(`Snapshot tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Snapshot tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(width, height, tileSize, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const pixels of this.#tiles.values()) bytes += pixels.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): PixelTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const pixels = this.#tiles.get(key);
    if (!pixels) return null;
    const region = this.tileRegion(column, row);
    return { key, column, row, ...region, pixels };
  }

  *tiles(): IterableIterator<PixelTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const column = key % this.columnCount;
      const row = Math.floor(key / this.columnCount);
      const tile = this.getTile(column, row);
      if (tile) yield tile;
    }
  }

  /** Produces an owned, deterministic representation suitable for workers and native containers. */
  snapshot(region?: PixelRegion): TiledPixelStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 1,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          pixels: new Uint8ClampedArray(tile.pixels),
        })),
    };
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield { x: tile.x, y: tile.y, width: tile.width, height: tile.height, pixels: tile.pixels };
      }
    }
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (const tile of this.pixelChunks(clipped)) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = ((y - tile.y) * tile.width + (overlap.x - tile.x)) * 4;
        const destinationStart = ((y - region.y) * region.width + (overlap.x - region.x)) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + overlap.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    const output = new Uint8ClampedArray(this.width * this.height * 4);
    for (const tile of this.tiles()) {
      for (let localY = 0; localY < tile.height; localY += 1) {
        const sourceStart = localY * tile.width * 4;
        const destinationStart = ((tile.y + localY) * this.width + tile.x) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + tile.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  write(patch: PixelPatch): PixelWriteResult {
    validatePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };

    const tiles = new Map(this.#tiles);
    const changedKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);

    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height * 4);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = ((y - patch.y) * patch.width + (x - patch.x)) * 4;
            const tileOffset = ((y - tileRegion.y) * tileRegion.width + (x - tileRegion.x)) * 4;
            let pixelChanged = false;
            for (let channel = 0; channel < 4; channel += 1) {
              const value = patch.pixels[sourceOffset + channel] ?? 0;
              if ((next[tileOffset + channel] ?? 0) !== value) {
                next[tileOffset + channel] = value;
                pixelChanged = true;
              }
            }
            if (pixelChanged) {
              tileChanged = true;
              dirtyLeft = Math.min(dirtyLeft, x);
              dirtyTop = Math.min(dirtyTop, y);
              dirtyRight = Math.max(dirtyRight, x);
              dirtyBottom = Math.max(dirtyBottom, y);
            }
          }
        }
        if (!tileChanged) continue;
        changedKeys.push(key);
        if (tileIsTransparent(next)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }

    if (changedKeys.length === 0) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    return {
      store: new TiledPixelStore(this.width, this.height, this.tileSize, tiles),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys: changedKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledPixelStoreDelta): TiledPixelStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed pixel tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed pixel tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Pixel delta tile ${String(index)} column`);
      integer(tile.row, `Pixel delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Pixel delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) throw new RangeError(`Pixel delta tile ${String(index)} is duplicated`);
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Pixel delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.pixels.length !== region.width * region.height * 4) {
        throw new RangeError(`Pixel delta tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Pixel delta tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(this.width, this.height, this.tileSize, tiles);
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

/** Immutable sparse one-channel storage for masks, selections, and channels. */
export class TiledCoverageStore implements CoverageSource {
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly columnCount: number;
  readonly rowCount: number;
  readonly defaultCoverage: number;
  readonly #tiles: ReadonlyMap<number, Uint8ClampedArray>;

  private constructor(
    width: number,
    height: number,
    tileSize: number,
    defaultCoverage: number,
    tiles: ReadonlyMap<number, Uint8ClampedArray>,
  ) {
    this.width = width;
    this.height = height;
    this.tileSize = tileSize;
    this.columnCount = Math.ceil(width / tileSize);
    this.rowCount = Math.ceil(height / tileSize);
    this.defaultCoverage = defaultCoverage;
    this.#tiles = tiles;
  }

  static empty(width: number, height: number, tileSize = DEFAULT_TILE_SIZE): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    return new TiledCoverageStore(width, height, tileSize, 0, new Map());
  }

  static uniform(
    width: number,
    height: number,
    defaultCoverage: number,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    integer(defaultCoverage, 'Default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Default coverage must be between 0 and 255');
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, new Map());
  }

  static fromContiguous(
    width: number,
    height: number,
    coverage: ArrayLike<number>,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    if (coverage.length !== width * height) {
      throw new RangeError('Coverage buffer length does not match its dimensions');
    }
    const store = TiledCoverageStore.empty(width, height, tileSize);
    return store.write({
      x: 0,
      y: 0,
      width,
      height,
      coverage: new Uint8ClampedArray(coverage),
    }).store;
  }

  static fromSnapshot(value: unknown): TiledCoverageStore {
    if (typeof value !== 'object' || value === null) {
      throw new TypeError('Tiled coverage snapshot must be an object');
    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1 && snapshot.schemaVersion !== 2) {
      throw new RangeError('Unsupported tiled coverage snapshot');
    }
    const width = snapshotInteger(snapshot.width, 'Coverage snapshot width');
    const height = snapshotInteger(snapshot.height, 'Coverage snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Coverage snapshot tile size');
    validateDimensions(width, height, tileSize);
    const defaultCoverage =
      snapshot.schemaVersion === 1
        ? 0
        : snapshotInteger(snapshot.defaultCoverage, 'Coverage snapshot default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Coverage snapshot default coverage must be between 0 and 255');
    }
    if (!Array.isArray(snapshot.tiles))
      throw new TypeError('Coverage snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Coverage snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Coverage snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Coverage snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key))
        throw new RangeError(`Coverage snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== tileWidth * tileHeight) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} length does not match its bounds`,
        );
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, defaultCoverage)) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} must differ from default coverage`,
        );
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const coverage of this.#tiles.values()) bytes += coverage.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): CoverageTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const coverage = this.#tiles.get(key);
    if (!coverage) return null;
    return { key, column, row, ...this.tileRegion(column, row), coverage };
  }

  *tiles(): IterableIterator<CoverageTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const tile = this.getTile(key % this.columnCount, Math.floor(key / this.columnCount));
      if (tile) yield tile;
    }
  }

  *coverageChunks(region?: PixelRegion): IterableIterator<CoveragePatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    if (this.defaultCoverage !== 0) {
      const firstColumn = Math.floor(requested.x / this.tileSize);
      const lastColumn = Math.floor((requested.x + requested.width - 1) / this.tileSize);
      const firstRow = Math.floor(requested.y / this.tileSize);
      const lastRow = Math.floor((requested.y + requested.height - 1) / this.tileSize);
      for (let row = firstRow; row <= lastRow; row += 1) {
        for (let column = firstColumn; column <= lastColumn; column += 1) {
          const tile = this.tileRegion(column, row);
          yield { ...tile, coverage: this.read(tile) };
        }
      }
      return;
    }
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield {
          x: tile.x,
          y: tile.y,
          width: tile.width,
          height: tile.height,
          coverage: tile.coverage,
        };
      }
    }
  }

  /** Inverts the implicit default and each deviation tile without visiting missing tiles. */
  invert(): TiledCoverageStore {
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [key, source] of this.#tiles) {
      const coverage = new Uint8ClampedArray(source.length);
      for (let index = 0; index < coverage.length; index += 1) {
        coverage[index] = 255 - (source[index] ?? this.defaultCoverage);
      }
      tiles.set(key, coverage);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      255 - this.defaultCoverage,
      tiles,
    );
  }

  snapshot(region?: PixelRegion): TiledCoverageStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 2,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      defaultCoverage: this.defaultCoverage,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          coverage: new Uint8ClampedArray(tile.coverage),
        })),
    };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    if (this.defaultCoverage !== 0) {
      for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
        const destinationStart = (y - region.y) * region.width + clipped.x - region.x;
        output.fill(this.defaultCoverage, destinationStart, destinationStart + clipped.width);
      }
    }
    for (const tile of this.tiles()) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = (y - tile.y) * tile.width + overlap.x - tile.x;
        const destinationStart = (y - region.y) * region.width + overlap.x - region.x;
        output.set(
          tile.coverage.subarray(sourceStart, sourceStart + overlap.width),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return this.read({ x: 0, y: 0, width: this.width, height: this.height });
  }

  write(patch: CoveragePatch): CoverageWriteResult {
    validateCoveragePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    const tiles = new Map(this.#tiles);
    const changedTileKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);
    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height).fill(this.defaultCoverage);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = (y - patch.y) * patch.width + x - patch.x;
            const tileOffset = (y - tileRegion.y) * tileRegion.width + x - tileRegion.x;
            const value = patch.coverage[sourceOffset] ?? 0;
            if ((next[tileOffset] ?? 0) === value) continue;
            next[tileOffset] = value;
            tileChanged = true;
            dirtyLeft = Math.min(dirtyLeft, x);
            dirtyTop = Math.min(dirtyTop, y);
            dirtyRight = Math.max(dirtyRight, x);
            dirtyBottom = Math.max(dirtyBottom, y);
          }
        }
        if (!tileChanged) continue;
        changedTileKeys.push(key);
        if (tileIsUniform(next, this.defaultCoverage)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }
    if (changedTileKeys.length === 0) {
      return { store: this, dirtyRegion: null, changedTileKeys: [] };
    }
    return {
      store: new TiledCoverageStore(
        this.width,
        this.height,
        this.tileSize,
        this.defaultCoverage,
        tiles,
      ),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledCoverageStoreDelta): TiledCoverageStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed coverage tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed coverage tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Coverage delta tile ${String(index)} column`);
      integer(tile.row, `Coverage delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Coverage delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) {
        throw new RangeError(`Coverage delta tile ${String(index)} is duplicated`);
      }
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== region.width * region.height) {
        throw new RangeError(`Coverage delta tile ${String(index)} length does not match bounds`);
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, this.defaultCoverage)) {
        throw new RangeError(`Coverage delta tile ${String(index)} must differ from default`);
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      this.defaultCoverage,
      tiles,
    );
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

export class ContiguousPixelSource implements PixelSource {
  readonly width: number;
  readonly height: number;
  readonly #pixels: Uint8ClampedArray;

  constructor(width: number, height: number, pixels: ArrayLike<number>) {
    validateDimensions(width, height, DEFAULT_TILE_SIZE);
    if (pixels.length !== width * height * 4) {
      throw new RangeError('Pixel buffer length does not match its dimensions');
    }
    this.width = width;
    this.height = height;
    this.#pixels = new Uint8ClampedArray(pixels);
  }

  get allocatedByteLength(): number {
    return this.#pixels.byteLength;
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    yield { ...requested, pixels: this.read(requested) };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
      const sourceStart = (y * this.width + clipped.x) * 4;
      const destinationStart = ((y - region.y) * region.width + (clipped.x - region.x)) * 4;
      output.set(
        this.#pixels.subarray(sourceStart, sourceStart + clipped.width * 4),
        destinationStart,
      );
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return new Uint8ClampedArray(this.#pixels);
  }
}

export function intersectRegions(left: PixelRegion, right: PixelRegion): PixelRegion | null {
  const x = Math.max(left.x, right.x);
  const y = Math.max(left.y, right.y);
  const rightEdge = Math.min(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.min(left.y + left.height, right.y + right.height);
  return rightEdge <= x || bottomEdge <= y
    ? null
    : { x, y, width: rightEdge - x, height: bottomEdge - y };
}

export function unionRegions(
  left: PixelRegion | null,
  right: PixelRegion | null,
): PixelRegion | null {
  if (!left) return right ? { ...right } : null;
  if (!right) return { ...left };
  const x = Math.min(left.x, right.x);
  const y = Math.min(left.y, right.y);
  const rightEdge = Math.max(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.max(left.y + left.height, right.y + right.height);
  return { x, y, width: rightEdge - x, height: bottomEdge - y };
}

function regionsTouch(left: PixelRegion, right: PixelRegion): boolean {
  return (
    left.x <= right.x + right.width &&
    right.x <= left.x + left.width &&
    left.y <= right.y + right.height &&
    right.y <= left.y + left.height
  );
}

function validateDimensions(width: number, height: number, tileSize: number): void {
  positiveInteger(width, 'Pixel store width');
  positiveInteger(height, 'Pixel store height');
  positiveInteger(tileSize, 'Tile size');
  if (tileSize > MAX_TILE_SIZE)
    throw new RangeError(`Tile size cannot exceed ${String(MAX_TILE_SIZE)}`);
}

function validatePatch(patch: PixelPatch): void {
  integer(patch.x, 'Patch x');
  integer(patch.y, 'Patch y');
  positiveInteger(patch.width, 'Patch width');
  positiveInteger(patch.height, 'Patch height');
  if (patch.pixels.length !== patch.width * patch.height * 4) {
    throw new RangeError('Patch pixel length does not match its dimensions');
  }
}

function validateCoveragePatch(patch: CoveragePatch): void {
  integer(patch.x, 'Coverage patch x');
  integer(patch.y, 'Coverage patch y');
  positiveInteger(patch.width, 'Coverage patch width');
  positiveInteger(patch.height, 'Coverage patch height');
  if (patch.coverage.length !== patch.width * patch.height) {
    throw new RangeError('Coverage patch length does not match its dimensions');
  }
}

function validateReadRegion(region: PixelRegion): void {
  integer(region.x, 'Read x');
  integer(region.y, 'Read y');
  positiveInteger(region.width, 'Read width');
  positiveInteger(region.height, 'Read height');
}

export const DEFAULT_TILE_SIZE = 256;
export const MAX_TILE_SIZE = 1024;

export interface PixelRegion {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface PixelPatch extends PixelRegion {
  readonly pixels: Uint8ClampedArray;
}

export interface PixelTile extends PixelRegion {
  readonly key: number;
  readonly column: number;
  readonly row: number;
  readonly pixels: Uint8ClampedArray;
}

export interface PixelSource {
  readonly width: number;
  readonly height: number;
  readonly allocatedByteLength: number;
  pixelChunks(region?: PixelRegion): Iterable<PixelPatch>;
  read(region: PixelRegion): Uint8ClampedArray;
  toContiguous(): Uint8ClampedArray;
}

export interface PixelWriteResult {
  readonly store: TiledPixelStore;
  readonly dirtyRegion: PixelRegion | null;
  readonly changedTileKeys: readonly number[];
}

export interface TiledPixelStoreSnapshot {
  readonly schemaVersion: 1;
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly tiles: readonly {
    readonly column: number;
    readonly row: number;
    readonly pixels: Uint8ClampedArray;
  }[];
}

export interface TiledPixelStoreDelta {
  readonly tiles: TiledPixelStoreSnapshot['tiles'];
  readonly removedTileKeys: readonly number[];
}

export interface CoveragePatch extends PixelRegion {
  readonly coverage: Uint8ClampedArray;
}

export interface CoverageSource {
  readonly width: number;
  readonly height: number;
  readonly allocatedByteLength: number;
  coverageChunks(region?: PixelRegion): Iterable<CoveragePatch>;
  read(region: PixelRegion): Uint8ClampedArray;
  toContiguous(): Uint8ClampedArray;
}

export class ContiguousCoverageSource implements CoverageSource {
  readonly allocatedByteLength: number;
  constructor(
    readonly width: number,
    readonly height: number,
    readonly coverage: Uint8ClampedArray,
  ) {
    validateDimensions(width, height, DEFAULT_TILE_SIZE);
    if (coverage.length !== width * height)
      throw new RangeError('Coverage buffer length does not match its dimensions');
    this.allocatedByteLength = coverage.byteLength;
  }
  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
      const start = y * this.width + clipped.x;
      const destination = (y - region.y) * region.width + clipped.x - region.x;
      output.set(this.coverage.subarray(start, start + clipped.width), destination);
    }
    return output;
  }
  *coverageChunks(region?: PixelRegion): IterableIterator<CoveragePatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    yield { ...requested, coverage: this.read(requested) };
  }
  toContiguous(): Uint8ClampedArray {
    return new Uint8ClampedArray(this.coverage);
  }
}

export interface CoverageTile extends PixelRegion {
  readonly key: number;
  readonly column: number;
  readonly row: number;
  readonly coverage: Uint8ClampedArray;
}

export interface CoverageWriteResult {
  readonly store: TiledCoverageStore;
  readonly dirtyRegion: PixelRegion | null;
  readonly changedTileKeys: readonly number[];
}

export interface TiledCoverageStoreSnapshot {
  readonly schemaVersion: 2;
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly defaultCoverage: number;
  readonly tiles: readonly {
    readonly column: number;
    readonly row: number;
    readonly coverage: Uint8ClampedArray;
  }[];
}

export interface TiledCoverageStoreDelta {
  readonly tiles: TiledCoverageStoreSnapshot['tiles'];
  readonly removedTileKeys: readonly number[];
}

export class DirtyRegionAccumulator {
  readonly #bounds: PixelRegion;
  readonly #maxRegions: number;
  #regions: PixelRegion[] = [];

  constructor(width: number, height: number, maxRegions = 32) {
    positiveInteger(width, 'Dirty-region width');
    positiveInteger(height, 'Dirty-region height');
    positiveInteger(maxRegions, 'Dirty-region limit');
    this.#bounds = { x: 0, y: 0, width, height };
    this.#maxRegions = maxRegions;
  }

  get size(): number {
    return this.#regions.length;
  }

  add(region: PixelRegion): void {
    const clipped = intersectRegions(region, this.#bounds);
    if (!clipped) return;
    let candidate = clipped;
    const remaining = [...this.#regions];
    for (let index = 0; index < remaining.length; ) {
      const current = remaining[index];
      if (regionsTouch(candidate, current)) {
        candidate = unionRegions(candidate, current) ?? candidate;
        remaining.splice(index, 1);
        index = 0;
      } else {
        index += 1;
      }
    }
    remaining.push(candidate);
    this.#regions = remaining;
    if (this.#regions.length > this.#maxRegions) {
      this.#regions = [
        this.#regions.reduce<PixelRegion | null>(
          (combined, item) => unionRegions(combined, item),
          null,
        ) ?? clipped,
      ];
    }
  }

  invalidateAll(): void {
    this.#regions = [{ ...this.#bounds }];
  }

  peek(): readonly PixelRegion[] {
    return this.#regions.map((region) => ({ ...region }));
  }

  consume(): readonly PixelRegion[] {
    const regions = this.peek();
    this.#regions = [];
    return regions;
  }
}

function positiveInteger(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value <= 0) throw new RangeError(`${label} must be positive`);
}

function integer(value: number, label: string): void {
  if (!Number.isSafeInteger(value)) throw new RangeError(`${label} must be an integer`);
}

function snapshotInteger(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value)) {
    throw new RangeError(`${label} must be an integer`);
  }
  return value;
}

function tileKey(column: number, row: number, columnCount: number): number {
  return row * columnCount + column;
}

function tileIsTransparent(pixels: Uint8ClampedArray): boolean {
  return pixels.every((value) => value === 0);
}

function tileIsUniform(values: Uint8ClampedArray, expected: number): boolean {
  for (let index = 0; index < values.length; index += 1) {
    if ((values[index] ?? 0) !== expected) return false;
  }
  return true;
}

export class TiledPixelStore {
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly columnCount: number;
  readonly rowCount: number;
  readonly #tiles: ReadonlyMap<number, Uint8ClampedArray>;

  private constructor(
    width: number,
    height: number,
    tileSize: number,
    tiles: ReadonlyMap<number, Uint8ClampedArray>,
  ) {
    this.width = width;
    this.height = height;
    this.tileSize = tileSize;
    this.columnCount = Math.ceil(width / tileSize);
    this.rowCount = Math.ceil(height / tileSize);
    this.#tiles = tiles;
  }

  static empty(width: number, height: number, tileSize = DEFAULT_TILE_SIZE): TiledPixelStore {
    validateDimensions(width, height, tileSize);
    return new TiledPixelStore(width, height, tileSize, new Map());
  }

  static fromContiguous(
    width: number,
    height: number,
    pixels: ArrayLike<number>,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledPixelStore {
    validateDimensions(width, height, tileSize);
    if (pixels.length !== width * height * 4) {
      throw new RangeError('Pixel buffer length does not match its dimensions');
    }
    const store = TiledPixelStore.empty(width, height, tileSize);
    return store.write({ x: 0, y: 0, width, height, pixels: new Uint8ClampedArray(pixels) }).store;
  }

  /** Rehydrates an owned sparse store from its worker/persistence boundary representation. */
  static fromSnapshot(value: unknown): TiledPixelStore {
    if (typeof value !== 'object' || value === null) {
      throw new TypeError('Tiled pixel snapshot must be an object');
    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1) throw new RangeError('Unsupported tiled pixel snapshot');
    const width = snapshotInteger(snapshot.width, 'Snapshot width');
    const height = snapshotInteger(snapshot.height, 'Snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Snapshot tile size');
    validateDimensions(width, height, tileSize);
    if (!Array.isArray(snapshot.tiles)) throw new TypeError('Snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key)) throw new RangeError(`Snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Snapshot tile ${String(index)} pixels must be Uint8ClampedArray`);
      }
      if (tile.pixels.length !== tileWidth * tileHeight * 4) {
        throw new RangeError(`Snapshot tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Snapshot tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(width, height, tileSize, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const pixels of this.#tiles.values()) bytes += pixels.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): PixelTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const pixels = this.#tiles.get(key);
    if (!pixels) return null;
    const region = this.tileRegion(column, row);
    return { key, column, row, ...region, pixels };
  }

  *tiles(): IterableIterator<PixelTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const column = key % this.columnCount;
      const row = Math.floor(key / this.columnCount);
      const tile = this.getTile(column, row);
      if (tile) yield tile;
    }
  }

  /** Produces an owned, deterministic representation suitable for workers and native containers. */
  snapshot(region?: PixelRegion): TiledPixelStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 1,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          pixels: new Uint8ClampedArray(tile.pixels),
        })),
    };
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield { x: tile.x, y: tile.y, width: tile.width, height: tile.height, pixels: tile.pixels };
      }
    }
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (const tile of this.pixelChunks(clipped)) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = ((y - tile.y) * tile.width + (overlap.x - tile.x)) * 4;
        const destinationStart = ((y - region.y) * region.width + (overlap.x - region.x)) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + overlap.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    const output = new Uint8ClampedArray(this.width * this.height * 4);
    for (const tile of this.tiles()) {
      for (let localY = 0; localY < tile.height; localY += 1) {
        const sourceStart = localY * tile.width * 4;
        const destinationStart = ((tile.y + localY) * this.width + tile.x) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + tile.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  write(patch: PixelPatch): PixelWriteResult {
    validatePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };

    const tiles = new Map(this.#tiles);
    const changedKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);

    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height * 4);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = ((y - patch.y) * patch.width + (x - patch.x)) * 4;
            const tileOffset = ((y - tileRegion.y) * tileRegion.width + (x - tileRegion.x)) * 4;
            let pixelChanged = false;
            for (let channel = 0; channel < 4; channel += 1) {
              const value = patch.pixels[sourceOffset + channel] ?? 0;
              if ((next[tileOffset + channel] ?? 0) !== value) {
                next[tileOffset + channel] = value;
                pixelChanged = true;
              }
            }
            if (pixelChanged) {
              tileChanged = true;
              dirtyLeft = Math.min(dirtyLeft, x);
              dirtyTop = Math.min(dirtyTop, y);
              dirtyRight = Math.max(dirtyRight, x);
              dirtyBottom = Math.max(dirtyBottom, y);
            }
          }
        }
        if (!tileChanged) continue;
        changedKeys.push(key);
        if (tileIsTransparent(next)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }

    if (changedKeys.length === 0) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    return {
      store: new TiledPixelStore(this.width, this.height, this.tileSize, tiles),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys: changedKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledPixelStoreDelta): TiledPixelStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed pixel tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed pixel tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Pixel delta tile ${String(index)} column`);
      integer(tile.row, `Pixel delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Pixel delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) throw new RangeError(`Pixel delta tile ${String(index)} is duplicated`);
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Pixel delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.pixels.length !== region.width * region.height * 4) {
        throw new RangeError(`Pixel delta tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Pixel delta tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(this.width, this.height, this.tileSize, tiles);
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

/** Immutable sparse one-channel storage for masks, selections, and channels. */
export class TiledCoverageStore implements CoverageSource {
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly columnCount: number;
  readonly rowCount: number;
  readonly defaultCoverage: number;
  readonly #tiles: ReadonlyMap<number, Uint8ClampedArray>;

  private constructor(
    width: number,
    height: number,
    tileSize: number,
    defaultCoverage: number,
    tiles: ReadonlyMap<number, Uint8ClampedArray>,
  ) {
    this.width = width;
    this.height = height;
    this.tileSize = tileSize;
    this.columnCount = Math.ceil(width / tileSize);
    this.rowCount = Math.ceil(height / tileSize);
    this.defaultCoverage = defaultCoverage;
    this.#tiles = tiles;
  }

  static empty(width: number, height: number, tileSize = DEFAULT_TILE_SIZE): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    return new TiledCoverageStore(width, height, tileSize, 0, new Map());
  }

  static uniform(
    width: number,
    height: number,
    defaultCoverage: number,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    integer(defaultCoverage, 'Default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Default coverage must be between 0 and 255');
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, new Map());
  }

  static fromContiguous(
    width: number,
    height: number,
    coverage: ArrayLike<number>,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    if (coverage.length !== width * height) {
      throw new RangeError('Coverage buffer length does not match its dimensions');
    }
    const store = TiledCoverageStore.empty(width, height, tileSize);
    return store.write({
      x: 0,
      y: 0,
      width,
      height,
      coverage: new Uint8ClampedArray(coverage),
    }).store;
  }

  static fromSnapshot(value: unknown): TiledCoverageStore {
    if (typeof value !== 'object' || value === null) {
      throw new TypeError('Tiled coverage snapshot must be an object');
    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1 && snapshot.schemaVersion !== 2) {
      throw new RangeError('Unsupported tiled coverage snapshot');
    }
    const width = snapshotInteger(snapshot.width, 'Coverage snapshot width');
    const height = snapshotInteger(snapshot.height, 'Coverage snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Coverage snapshot tile size');
    validateDimensions(width, height, tileSize);
    const defaultCoverage =
      snapshot.schemaVersion === 1
        ? 0
        : snapshotInteger(snapshot.defaultCoverage, 'Coverage snapshot default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Coverage snapshot default coverage must be between 0 and 255');
    }
    if (!Array.isArray(snapshot.tiles))
      throw new TypeError('Coverage snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Coverage snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Coverage snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Coverage snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key))
        throw new RangeError(`Coverage snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== tileWidth * tileHeight) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} length does not match its bounds`,
        );
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, defaultCoverage)) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} must differ from default coverage`,
        );
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const coverage of this.#tiles.values()) bytes += coverage.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): CoverageTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const coverage = this.#tiles.get(key);
    if (!coverage) return null;
    return { key, column, row, ...this.tileRegion(column, row), coverage };
  }

  *tiles(): IterableIterator<CoverageTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const tile = this.getTile(key % this.columnCount, Math.floor(key / this.columnCount));
      if (tile) yield tile;
    }
  }

  *coverageChunks(region?: PixelRegion): IterableIterator<CoveragePatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    if (this.defaultCoverage !== 0) {
      const firstColumn = Math.floor(requested.x / this.tileSize);
      const lastColumn = Math.floor((requested.x + requested.width - 1) / this.tileSize);
      const firstRow = Math.floor(requested.y / this.tileSize);
      const lastRow = Math.floor((requested.y + requested.height - 1) / this.tileSize);
      for (let row = firstRow; row <= lastRow; row += 1) {
        for (let column = firstColumn; column <= lastColumn; column += 1) {
          const tile = this.tileRegion(column, row);
          yield { ...tile, coverage: this.read(tile) };
        }
      }
      return;
    }
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield {
          x: tile.x,
          y: tile.y,
          width: tile.width,
          height: tile.height,
          coverage: tile.coverage,
        };
      }
    }
  }

  /** Inverts the implicit default and each deviation tile without visiting missing tiles. */
  invert(): TiledCoverageStore {
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [key, source] of this.#tiles) {
      const coverage = new Uint8ClampedArray(source.length);
      for (let index = 0; index < coverage.length; index += 1) {
        coverage[index] = 255 - (source[index] ?? this.defaultCoverage);
      }
      tiles.set(key, coverage);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      255 - this.defaultCoverage,
      tiles,
    );
  }

  snapshot(region?: PixelRegion): TiledCoverageStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 2,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      defaultCoverage: this.defaultCoverage,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          coverage: new Uint8ClampedArray(tile.coverage),
        })),
    };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    if (this.defaultCoverage !== 0) {
      for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
        const destinationStart = (y - region.y) * region.width + clipped.x - region.x;
        output.fill(this.defaultCoverage, destinationStart, destinationStart + clipped.width);
      }
    }
    for (const tile of this.tiles()) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = (y - tile.y) * tile.width + overlap.x - tile.x;
        const destinationStart = (y - region.y) * region.width + overlap.x - region.x;
        output.set(
          tile.coverage.subarray(sourceStart, sourceStart + overlap.width),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return this.read({ x: 0, y: 0, width: this.width, height: this.height });
  }

  write(patch: CoveragePatch): CoverageWriteResult {
    validateCoveragePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    const tiles = new Map(this.#tiles);
    const changedTileKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);
    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height).fill(this.defaultCoverage);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = (y - patch.y) * patch.width + x - patch.x;
            const tileOffset = (y - tileRegion.y) * tileRegion.width + x - tileRegion.x;
            const value = patch.coverage[sourceOffset] ?? 0;
            if ((next[tileOffset] ?? 0) === value) continue;
            next[tileOffset] = value;
            tileChanged = true;
            dirtyLeft = Math.min(dirtyLeft, x);
            dirtyTop = Math.min(dirtyTop, y);
            dirtyRight = Math.max(dirtyRight, x);
            dirtyBottom = Math.max(dirtyBottom, y);
          }
        }
        if (!tileChanged) continue;
        changedTileKeys.push(key);
        if (tileIsUniform(next, this.defaultCoverage)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }
    if (changedTileKeys.length === 0) {
      return { store: this, dirtyRegion: null, changedTileKeys: [] };
    }
    return {
      store: new TiledCoverageStore(
        this.width,
        this.height,
        this.tileSize,
        this.defaultCoverage,
        tiles,
      ),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledCoverageStoreDelta): TiledCoverageStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed coverage tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed coverage tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Coverage delta tile ${String(index)} column`);
      integer(tile.row, `Coverage delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Coverage delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) {
        throw new RangeError(`Coverage delta tile ${String(index)} is duplicated`);
      }
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== region.width * region.height) {
        throw new RangeError(`Coverage delta tile ${String(index)} length does not match bounds`);
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, this.defaultCoverage)) {
        throw new RangeError(`Coverage delta tile ${String(index)} must differ from default`);
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      this.defaultCoverage,
      tiles,
    );
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

export class ContiguousPixelSource implements PixelSource {
  readonly width: number;
  readonly height: number;
  readonly #pixels: Uint8ClampedArray;

  constructor(width: number, height: number, pixels: ArrayLike<number>) {
    validateDimensions(width, height, DEFAULT_TILE_SIZE);
    if (pixels.length !== width * height * 4) {
      throw new RangeError('Pixel buffer length does not match its dimensions');
    }
    this.width = width;
    this.height = height;
    this.#pixels = new Uint8ClampedArray(pixels);
  }

  get allocatedByteLength(): number {
    return this.#pixels.byteLength;
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    yield { ...requested, pixels: this.read(requested) };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
      const sourceStart = (y * this.width + clipped.x) * 4;
      const destinationStart = ((y - region.y) * region.width + (clipped.x - region.x)) * 4;
      output.set(
        this.#pixels.subarray(sourceStart, sourceStart + clipped.width * 4),
        destinationStart,
      );
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return new Uint8ClampedArray(this.#pixels);
  }
}

export function intersectRegions(left: PixelRegion, right: PixelRegion): PixelRegion | null {
  const x = Math.max(left.x, right.x);
  const y = Math.max(left.y, right.y);
  const rightEdge = Math.min(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.min(left.y + left.height, right.y + right.height);
  return rightEdge <= x || bottomEdge <= y
    ? null
    : { x, y, width: rightEdge - x, height: bottomEdge - y };
}

export function unionRegions(
  left: PixelRegion | null,
  right: PixelRegion | null,
): PixelRegion | null {
  if (!left) return right ? { ...right } : null;
  if (!right) return { ...left };
  const x = Math.min(left.x, right.x);
  const y = Math.min(left.y, right.y);
  const rightEdge = Math.max(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.max(left.y + left.height, right.y + right.height);
  return { x, y, width: rightEdge - x, height: bottomEdge - y };
}

function regionsTouch(left: PixelRegion, right: PixelRegion): boolean {
  return (
    left.x <= right.x + right.width &&
    right.x <= left.x + left.width &&
    left.y <= right.y + right.height &&
    right.y <= left.y + left.height
  );
}

function validateDimensions(width: number, height: number, tileSize: number): void {
  positiveInteger(width, 'Pixel store width');
  positiveInteger(height, 'Pixel store height');
  positiveInteger(tileSize, 'Tile size');
  if (tileSize > MAX_TILE_SIZE)
    throw new RangeError(`Tile size cannot exceed ${String(MAX_TILE_SIZE)}`);
}

function validatePatch(patch: PixelPatch): void {
  integer(patch.x, 'Patch x');
  integer(patch.y, 'Patch y');
  positiveInteger(patch.width, 'Patch width');
  positiveInteger(patch.height, 'Patch height');
  if (patch.pixels.length !== patch.width * patch.height * 4) {
    throw new RangeError('Patch pixel length does not match its dimensions');
  }
}

function validateCoveragePatch(patch: CoveragePatch): void {
  integer(patch.x, 'Coverage patch x');
  integer(patch.y, 'Coverage patch y');
  positiveInteger(patch.width, 'Coverage patch width');
  positiveInteger(patch.height, 'Coverage patch height');
  if (patch.coverage.length !== patch.width * patch.height) {
    throw new RangeError('Coverage patch length does not match its dimensions');
  }
}

function validateReadRegion(region: PixelRegion): void {
  integer(region.x, 'Read x');
  integer(region.y, 'Read y');
  positiveInteger(region.width, 'Read width');
  positiveInteger(region.height, 'Read height');
}

export interface Command<State> {
  readonly label?: string;
  execute(state: State): State;
}

export interface HistoryOptions {
  /** Maximum undo entries retained. Defaults to 100. */
  readonly capacity?: number;
}

interface Entry<State> {
  readonly before: State;
  readonly after: State;
  readonly label?: string;
}

export class CommandHistory<State> {
  readonly #capacity: number;
  #state: State;
  #undoStack: Entry<State>[] = [];
  #redoStack: Entry<State>[] = [];

  constructor(initialState: State, options: HistoryOptions = {}) {
    const capacity = options.capacity ?? 100;
    if (!Number.isSafeInteger(capacity) || capacity < 0) {
      throw new RangeError('History capacity must be a non-negative integer');
    }
    this.#state = initialState;
    this.#capacity = capacity;
  }

  get state(): State {
    return this.#state;
  }

  get canUndo(): boolean {
    return this.#undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.#redoStack.length > 0;
  }

  get undoCount(): number {
    return this.#undoStack.length;
  }

  get redoCount(): number {
    return this.#redoStack.length;
  }

  get nextUndoLabel(): string | undefined {
    return this.#undoStack.at(-1)?.label;
  }

  get nextRedoLabel(): string | undefined {
    return this.#redoStack.at(-1)?.label;
  }

  execute(command: Command<State>): State {
    const before = this.#state;
    const after = command.execute(before);
    this.#state = after;
    this.#redoStack = [];
    if (this.#capacity > 0 && after !== before) {
      const entry: Entry<State> =
        command.label === undefined ? { before, after } : { before, after, label: command.label };
      this.#undoStack.push(entry);
      if (this.#undoStack.length > this.#capacity) this.#undoStack.shift();
    }
    return this.#state;
  }

  undo(): State {
    const entry = this.#undoStack.pop();
    if (entry === undefined) return this.#state;
    this.#state = entry.before;
    this.#redoStack.push(entry);
    return this.#state;
  }

  redo(): State {
    const entry = this.#redoStack.pop();
    if (entry === undefined) return this.#state;
    this.#state = entry.after;
    this.#undoStack.push(entry);
    return this.#state;
  }

  clear(): void {
    this.#undoStack = [];
    this.#redoStack = [];
  }

  /** Replaces the current state and discards all history. */
  reset(state: State): void {
    this.#state = state;
    this.clear();
  }
}

import {
  createAlphaChannel,
  createSelectionMask,
  type DocumentTransform,
  type ImageDocument,
  type Layer,
  type LayerTransform,
  type PathCommand,
  type PixelLayer,
  type PixelPatch,
  type RasterMask,
  type SelectionMask,
} from '@freetoshop/core-document';
import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

export type ResamplingMethod = 'nearest' | 'bilinear';

export interface ResizeImageOptions {
  readonly width: number;
  readonly height: number;
  readonly method: ResamplingMethod;
}

export interface BrushPoint {
  /** Document-space x coordinate. */
  readonly x: number;
  /** Document-space y coordinate. */
  readonly y: number;
  /** Optional normalized tablet pressure. Defaults to 1. */
  readonly pressure?: number;
}

export interface BrushOptions {
  readonly mode: 'source-over' | 'erase';
  /** Diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  readonly color: readonly [number, number, number, number];
}

export interface MaskBrushOptions {
  readonly mode: 'reveal' | 'conceal';
  /** Diameter in document pixels. A size of zero is a no-op. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
}

export interface CoveragePatch {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly coverage: Uint8ClampedArray;
}

interface Bounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

const MAX_IMAGE_DIMENSION = 32_768;
const MAX_IMAGE_PIXELS = 100_000_000;
const MAX_RESIZE_WORKING_BYTES = 1_000_000_000;

function validateOutputSize(width: number, height: number, label = 'Image'): void {
  if (!Number.isSafeInteger(width) || width <= 0) {
    throw new RangeError(`${label} width must be a positive integer`);
  }
  if (!Number.isSafeInteger(height) || height <= 0) {
    throw new RangeError(`${label} height must be a positive integer`);
  }
  if (width > MAX_IMAGE_DIMENSION || height > MAX_IMAGE_DIMENSION) {
    throw new RangeError(`${label} dimensions cannot exceed ${String(MAX_IMAGE_DIMENSION)} pixels`);
  }
  if (!Number.isSafeInteger(width * height) || width * height > MAX_IMAGE_PIXELS) {
    throw new RangeError(`${label} area cannot exceed ${String(MAX_IMAGE_PIXELS)} pixels`);
  }
}

function validateResamplingMethod(method: string): asserts method is ResamplingMethod {
  if (method !== 'nearest' && method !== 'bilinear') {
    throw new RangeError('Resampling method must be nearest or bilinear');
  }
}

function sourceCoordinate(
  destination: number,
  sourceSize: number,
  destinationSize: number,
): number {
  return ((destination + 0.5) * sourceSize) / destinationSize - 0.5;
}

function clampIndex(value: number, size: number): number {
  return Math.max(0, Math.min(size - 1, value));
}

/** Resamples single-channel 8-bit coverage at pixel centers. */
export function resampleCoverage(
  source: ArrayLike<number>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): Uint8ClampedArray {
  validateOutputSize(sourceWidth, sourceHeight, 'Source coverage');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination coverage');
  if (source.length !== sourceWidth * sourceHeight) {
    throw new RangeError('Coverage buffer length does not match its dimensions');
  }
  validateResamplingMethod(method);
  const result = new Uint8ClampedArray(destinationWidth * destinationHeight);
  for (let y = 0; y < destinationHeight; y += 1) {
    const sourceY = sourceCoordinate(y, sourceHeight, destinationHeight);
    if (method === 'nearest') {
      const sampleY = clampIndex(Math.round(sourceY), sourceHeight);
      for (let x = 0; x < destinationWidth; x += 1) {
        const sampleX = clampIndex(
          Math.round(sourceCoordinate(x, sourceWidth, destinationWidth)),
          sourceWidth,
        );
        result[y * destinationWidth + x] = source[sampleY * sourceWidth + sampleX] ?? 0;
      }
      continue;
    }
    const y0 = Math.floor(sourceY);
    const y1 = y0 + 1;
    const yWeight = sourceY - y0;
    for (let x = 0; x < destinationWidth; x += 1) {
      const sourceX = sourceCoordinate(x, sourceWidth, destinationWidth);
      const x0 = Math.floor(sourceX);
      const x1 = x0 + 1;
      const xWeight = sourceX - x0;
      const sample = (sampleX: number, sampleY: number) =>
        source[
          clampIndex(sampleY, sourceHeight) * sourceWidth + clampIndex(sampleX, sourceWidth)
        ] ?? 0;
      const top = sample(x0, y0) * (1 - xWeight) + sample(x1, y0) * xWeight;
      const bottom = sample(x0, y1) * (1 - xWeight) + sample(x1, y1) * xWeight;
      result[y * destinationWidth + x] = Math.round(top * (1 - yWeight) + bottom * yWeight);
    }
  }
  return result;
}

function destinationTileKeys(
  sourceTiles: Iterable<{ x: number; y: number; width: number; height: number }>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  destinationTileSize: number,
): number[] {
  const columnCount = Math.ceil(destinationWidth / destinationTileSize);
  const keys = new Set<number>();
  for (const tile of sourceTiles) {
    const left = Math.max(0, Math.floor((tile.x * destinationWidth) / sourceWidth) - 1);
    const top = Math.max(0, Math.floor((tile.y * destinationHeight) / sourceHeight) - 1);
    const right = Math.min(
      destinationWidth - 1,
      Math.ceil(((tile.x + tile.width) * destinationWidth) / sourceWidth) + 1,
    );
    const bottom = Math.min(
      destinationHeight - 1,
      Math.ceil(((tile.y + tile.height) * destinationHeight) / sourceHeight) + 1,
    );
    for (
      let row = Math.floor(top / destinationTileSize);
      row <= Math.floor(bottom / destinationTileSize);
      row += 1
    ) {
      for (
        let column = Math.floor(left / destinationTileSize);
        column <= Math.floor(right / destinationTileSize);
        column += 1
      ) {
        keys.add(row * columnCount + column);
      }
    }
  }
  return [...keys].sort((left, right) => left - right);
}

function destinationTileRegion(
  key: number,
  width: number,
  height: number,
  tileSize: number,
): { x: number; y: number; width: number; height: number } {
  const columnCount = Math.ceil(width / tileSize);
  const column = key % columnCount;
  const row = Math.floor(key / columnCount);
  const x = column * tileSize;
  const y = row * tileSize;
  return {
    x,
    y,
    width: Math.min(tileSize, width - x),
    height: Math.min(tileSize, height - y),
  };
}

function coverageStoreSample(store: TiledCoverageStore, x: number, y: number): number {
  const sampleX = clampIndex(x, store.width);
  const sampleY = clampIndex(y, store.height);
  const tile = store.getTile(
    Math.floor(sampleX / store.tileSize),
    Math.floor(sampleY / store.tileSize),
  );
  if (tile === null) return store.defaultCoverage;
  return tile.coverage[(sampleY - tile.y) * tile.width + sampleX - tile.x] ?? store.defaultCoverage;
}

/** Resamples coverage one destination tile at a time without a source-span intermediate. */
export function resampleCoverageStore(
  store: TiledCoverageStore,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): TiledCoverageStore {
  validateOutputSize(store.width, store.height, 'Source coverage');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination coverage');
  validateResamplingMethod(method);
  let result = TiledCoverageStore.uniform(
    destinationWidth,
    destinationHeight,
    store.defaultCoverage,
    store.tileSize,
  );
  for (const key of destinationTileKeys(
    store.tiles(),
    store.width,
    store.height,
    destinationWidth,
    destinationHeight,
    result.tileSize,
  )) {
    const region = destinationTileRegion(key, destinationWidth, destinationHeight, result.tileSize);
    const coverage = new Uint8ClampedArray(region.width * region.height);
    for (let y = 0; y < region.height; y += 1) {
      const destinationY = region.y + y;
      const sourceY = sourceCoordinate(destinationY, store.height, destinationHeight);
      for (let x = 0; x < region.width; x += 1) {
        const destinationX = region.x + x;
        const sourceX = sourceCoordinate(destinationX, store.width, destinationWidth);
        if (method === 'nearest') {
          coverage[y * region.width + x] = coverageStoreSample(
            store,
            Math.round(sourceX),
            Math.round(sourceY),
          );
          continue;
        }
        const x0 = Math.floor(sourceX);
        const y0 = Math.floor(sourceY);
        const xWeight = sourceX - x0;
        const yWeight = sourceY - y0;
        const top =
          coverageStoreSample(store, x0, y0) * (1 - xWeight) +
          coverageStoreSample(store, x0 + 1, y0) * xWeight;
        const bottom =
          coverageStoreSample(store, x0, y0 + 1) * (1 - xWeight) +
          coverageStoreSample(store, x0 + 1, y0 + 1) * xWeight;
        coverage[y * region.width + x] = Math.round(top * (1 - yWeight) + bottom * yWeight);
      }
    }
    result = result.write({ ...region, coverage }).store;
  }
  return result;
}

/** Resamples straight-alpha RGBA without introducing transparent-color fringes. */
export function resamplePixels(
  source: ArrayLike<number>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): Uint8ClampedArray {
  validateOutputSize(sourceWidth, sourceHeight, 'Source image');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination image');
  if (source.length !== sourceWidth * sourceHeight * 4) {
    throw new RangeError('Pixel buffer length does not match its dimensions');
  }
  validateResamplingMethod(method);
  const result = new Uint8ClampedArray(destinationWidth * destinationHeight * 4);
  for (let y = 0; y < destinationHeight; y += 1) {
    const sourceY = sourceCoordinate(y, sourceHeight, destinationHeight);
    for (let x = 0; x < destinationWidth; x += 1) {
      const sourceX = sourceCoordinate(x, sourceWidth, destinationWidth);
      const destinationOffset = (y * destinationWidth + x) * 4;
      if (method === 'nearest') {
        const sampleX = clampIndex(Math.round(sourceX), sourceWidth);
        const sampleY = clampIndex(Math.round(sourceY), sourceHeight);
        const sourceOffset = (sampleY * sourceWidth + sampleX) * 4;
        for (let channel = 0; channel < 4; channel += 1) {
          result[destinationOffset + channel] = source[sourceOffset + channel] ?? 0;
        }
        continue;
      }
      const x0 = Math.floor(sourceX);
      const y0 = Math.floor(sourceY);
      const xWeight = sourceX - x0;
      const yWeight = sourceY - y0;
      const samples = [
        { x: x0, y: y0, weight: (1 - xWeight) * (1 - yWeight) },
        { x: x0 + 1, y: y0, weight: xWeight * (1 - yWeight) },
        { x: x0, y: y0 + 1, weight: (1 - xWeight) * yWeight },
        { x: x0 + 1, y: y0 + 1, weight: xWeight * yWeight },
      ];
      let alpha = 0;
      const premultiplied = [0, 0, 0];
      for (const sample of samples) {
        const sampleOffset =
          (clampIndex(sample.y, sourceHeight) * sourceWidth + clampIndex(sample.x, sourceWidth)) *
          4;
        const sampleAlpha = (source[sampleOffset + 3] ?? 0) / 255;
        alpha += sampleAlpha * sample.weight;
        for (let channel = 0; channel < 3; channel += 1) {
          premultiplied[channel] =
            (premultiplied[channel] ?? 0) +
            (source[sampleOffset + channel] ?? 0) * sampleAlpha * sample.weight;
        }
      }
      result[destinationOffset + 3] = Math.round(alpha * 255);
      for (let channel = 0; channel < 3; channel += 1) {
        result[destinationOffset + channel] =
          alpha === 0 ? 0 : Math.round((premultiplied[channel] ?? 0) / alpha);
      }
    }
  }
  return result;
}

function pixelStoreSample(store: TiledPixelStore, x: number, y: number, channel: number): number {
  const sampleX = clampIndex(x, store.width);
  const sampleY = clampIndex(y, store.height);
  const tile = store.getTile(
    Math.floor(sampleX / store.tileSize),
    Math.floor(sampleY / store.tileSize),
  );
  if (tile === null) return 0;
  return tile.pixels[((sampleY - tile.y) * tile.width + sampleX - tile.x) * 4 + channel] ?? 0;
}

/**
 * Resamples a tiled pixel store one destination tile at a time. Sampling reads
 * canonical source tiles directly, so distant sparse tiles never create a dense span.
 */
export function resamplePixelStore(
  store: TiledPixelStore,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): TiledPixelStore {
  validateOutputSize(store.width, store.height, 'Source image');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination image');
  validateResamplingMethod(method);
  let result = TiledPixelStore.empty(destinationWidth, destinationHeight, store.tileSize);
  for (const key of destinationTileKeys(
    store.tiles(),
    store.width,
    store.height,
    destinationWidth,
    destinationHeight,
    result.tileSize,
  )) {
    const region = destinationTileRegion(key, destinationWidth, destinationHeight, result.tileSize);
    const pixels = new Uint8ClampedArray(region.width * region.height * 4);
    for (let y = 0; y < region.height; y += 1) {
      const sourceY = sourceCoordinate(region.y + y, store.height, destinationHeight);
      for (let x = 0; x < region.width; x += 1) {
        const sourceX = sourceCoordinate(region.x + x, store.width, destinationWidth);
        const destinationOffset = (y * region.width + x) * 4;
        if (method === 'nearest') {
          for (let channel = 0; channel < 4; channel += 1) {
            pixels[destinationOffset + channel] = pixelStoreSample(
              store,
              Math.round(sourceX),
              Math.round(sourceY),
              channel,
            );
          }
          continue;
        }
        const x0 = Math.floor(sourceX);
        const y0 = Math.floor(sourceY);
        const xWeight = sourceX - x0;
        const yWeight = sourceY - y0;
        const samples = [
          { x: x0, y: y0, weight: (1 - xWeight) * (1 - yWeight) },
          { x: x0 + 1, y: y0, weight: xWeight * (1 - yWeight) },
          { x: x0, y: y0 + 1, weight: (1 - xWeight) * yWeight },
          { x: x0 + 1, y: y0 + 1, weight: xWeight * yWeight },
        ];
        let alpha = 0;
        const premultiplied = [0, 0, 0];
        for (const sample of samples) {
          const sampleAlpha = pixelStoreSample(store, sample.x, sample.y, 3) / 255;
          alpha += sampleAlpha * sample.weight;
          for (let channel = 0; channel < 3; channel += 1) {
            premultiplied[channel] =
              (premultiplied[channel] ?? 0) +
              pixelStoreSample(store, sample.x, sample.y, channel) * sampleAlpha * sample.weight;
          }
        }
        pixels[destinationOffset + 3] = Math.round(alpha * 255);
        for (let channel = 0; channel < 3; channel += 1) {
          pixels[destinationOffset + channel] =
            alpha === 0 ? 0 : Math.round((premultiplied[channel] ?? 0) / alpha);
        }
      }
    }
    result = result.write({ ...region, pixels }).store;
  }
  return result;
}

function multiplyTransforms(left: LayerTransform, right: LayerTransform): LayerTransform {
  return {
    a: left.a * right.a + left.c * right.b,
    b: left.b * right.a + left.d * right.b,
    c: left.a * right.c + left.c * right.d,
    d: left.b * right.c + left.d * right.d,
    e: left.a * right.e + left.c * right.f + left.e,
    f: left.b * right.e + left.d * right.f + left.f,
  };
}

function scalePathCommand(command: PathCommand, scaleX: number, scaleY: number): PathCommand {
  if (command.type === 'close') return { type: 'close' };
  if (command.type === 'move' || command.type === 'line') {
    return { type: command.type, x: command.x * scaleX, y: command.y * scaleY };
  }
  return {
    type: 'cubic',
    control1X: command.control1X * scaleX,
    control1Y: command.control1Y * scaleY,
    control2X: command.control2X * scaleX,
    control2Y: command.control2Y * scaleY,
    x: command.x * scaleX,
    y: command.y * scaleY,
  };
}

function resizeLayer(
  layer: Layer,
  documentScale: LayerTransform,
  scaleX: number,
  scaleY: number,
  method: ResamplingMethod,
  isRoot: boolean,
): Layer {
  if (layer.kind === 'group') {
    return {
      ...layer,
      transform: isRoot ? multiplyTransforms(documentScale, layer.transform) : layer.transform,
      rasterMask:
        layer.rasterMask === null
          ? null
          : {
              ...layer.rasterMask,
              width: Math.max(1, Math.round(layer.rasterMask.width * scaleX)),
              height: Math.max(1, Math.round(layer.rasterMask.height * scaleY)),
              coverageStore: resampleCoverageStore(
                layer.rasterMask.coverageStore,
                Math.max(1, Math.round(layer.rasterMask.width * scaleX)),
                Math.max(1, Math.round(layer.rasterMask.height * scaleY)),
                method,
              ),
            },
      vectorMask:
        layer.vectorMask === null
          ? null
          : {
              ...layer.vectorMask,
              width: Math.max(1, Math.round(layer.vectorMask.width * scaleX)),
              height: Math.max(1, Math.round(layer.vectorMask.height * scaleY)),
              commands: layer.vectorMask.commands.map((command) =>
                scalePathCommand(command, scaleX, scaleY),
              ),
            },
      children: layer.children.map((child) =>
        resizeLayer(child, documentScale, scaleX, scaleY, method, false),
      ),
    };
  }
  if (layer.kind === 'adjustment') {
    return {
      ...layer,
      transform: isRoot ? multiplyTransforms(documentScale, layer.transform) : layer.transform,
      rasterMask:
        layer.rasterMask === null
          ? null
          : {
              ...layer.rasterMask,
              width: Math.max(1, Math.round(layer.rasterMask.width * scaleX)),
              height: Math.max(1, Math.round(layer.rasterMask.height * scaleY)),
              coverageStore: resampleCoverageStore(
                layer.rasterMask.coverageStore,
                Math.max(1, Math.round(layer.rasterMask.width * scaleX)),
                Math.max(1, Math.round(layer.rasterMask.height * scaleY)),
                method,
              ),
            },
      vectorMask:
        layer.vectorMask === null
          ? null
          : {
              ...layer.vectorMask,
              width: Math.max(1, Math.round(layer.vectorMask.width * scaleX)),
              height: Math.max(1, Math.round(layer.vectorMask.height * scaleY)),
              commands: layer.vectorMask.commands.map((command) =>
                scalePathCommand(command, scaleX, scaleY),
              ),
            },
    };
  }
  if (layer.kind === 'shape' || layer.kind === 'text' || layer.kind === 'smart-object') {
    return {
      ...layer,
      transform: isRoot ? multiplyTransforms(documentScale, layer.transform) : layer.transform,
    };
  }
  const width = Math.max(1, Math.round(layer.width * scaleX));
  const height = Math.max(1, Math.round(layer.height * scaleY));
  validateOutputSize(width, height, `Layer ${layer.name}`);
  const localInverseScale: LayerTransform = {
    a: layer.width / width,
    b: 0,
    c: 0,
    d: layer.height / height,
    e: 0,
    f: 0,
  };
  return {
    ...layer,
    width,
    height,
    pixelStore: resamplePixelStore(layer.pixelStore, width, height, method),
    transform: multiplyTransforms(
      isRoot ? documentScale : { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 },
      multiplyTransforms(layer.transform, localInverseScale),
    ),
    rasterMask: layer.rasterMask
      ? {
          ...layer.rasterMask,
          width,
          height,
          coverageStore: resampleCoverageStore(
            layer.rasterMask.coverageStore,
            width,
            height,
            method,
          ),
        }
      : null,
    vectorMask: layer.vectorMask
      ? {
          ...layer.vectorMask,
          width,
          height,
          commands: layer.vectorMask.commands.map((command) =>
            scalePathCommand(command, width / layer.width, height / layer.height),
          ),
        }
      : null,
  };
}

function estimateLayerResizeBytes(
  layers: readonly Layer[],
  scaleX: number,
  scaleY: number,
): number {
  let bytes = 0;
  for (const layer of layers) {
    if (layer.kind === 'group') {
      bytes += estimateLayerResizeBytes(layer.children, scaleX, scaleY);
      continue;
    }
    if (layer.kind === 'adjustment') {
      if (layer.rasterMask !== null) {
        const width = Math.max(1, Math.round(layer.rasterMask.width * scaleX));
        const height = Math.max(1, Math.round(layer.rasterMask.height * scaleY));
        validateOutputSize(width, height, `Layer ${layer.name} mask`);
        bytes += width * height;
      }
      continue;
    }
    if (layer.kind === 'shape' || layer.kind === 'text' || layer.kind === 'smart-object') continue;
    const width = Math.max(1, Math.round(layer.width * scaleX));
    const height = Math.max(1, Math.round(layer.height * scaleY));
    validateOutputSize(width, height, `Layer ${layer.name}`);
    bytes += width * height * (layer.rasterMask ? 5 : 4);
    if (!Number.isSafeInteger(bytes) || bytes > MAX_RESIZE_WORKING_BYTES) {
      throw new RangeError(
        `Resize working set cannot exceed ${String(MAX_RESIZE_WORKING_BYTES)} bytes`,
      );
    }
  }
  return bytes;
}

/** Resamples all raster content and document-space masks as one undoable image-size operation. */
export function resizeImage(options: ResizeImageOptions): DocumentTransform {
  validateOutputSize(options.width, options.height);
  validateResamplingMethod(options.method);
  const ownedOptions = { ...options };
  return {
    label: 'Resize image',
    execute(document: ImageDocument): ImageDocument {
      if (
        ownedOptions.width === document.canvas.width &&
        ownedOptions.height === document.canvas.height
      ) {
        return document;
      }
      const scaleX = ownedOptions.width / document.canvas.width;
      const scaleY = ownedOptions.height / document.canvas.height;
      const documentScale: LayerTransform = {
        a: scaleX,
        b: 0,
        c: 0,
        d: scaleY,
        e: 0,
        f: 0,
      };
      const coverageBytes =
        ownedOptions.width *
        ownedOptions.height *
        (document.channels.length + (document.selection === null ? 0 : 1));
      const workingBytes =
        estimateLayerResizeBytes(document.layers, scaleX, scaleY) + coverageBytes;
      if (!Number.isSafeInteger(workingBytes) || workingBytes > MAX_RESIZE_WORKING_BYTES) {
        throw new RangeError(
          `Resize working set cannot exceed ${String(MAX_RESIZE_WORKING_BYTES)} bytes`,
        );
      }
      return {
        ...document,
        canvas: { width: ownedOptions.width, height: ownedOptions.height },
        layers: document.layers.map((layer) =>
          resizeLayer(layer, documentScale, scaleX, scaleY, ownedOptions.method, true),
        ),
        selection:
          document.selection === null
            ? null
            : createSelectionMask({
                width: ownedOptions.width,
                height: ownedOptions.height,
                // Sparse-aware resample: empty stays empty; active bounds only densify.
                coverageStore: resampleCoverageStore(
                  document.selection.coverageStore,
                  ownedOptions.width,
                  ownedOptions.height,
                  ownedOptions.method,
                ),
              }),
        channels: document.channels.map((channel) =>
          createAlphaChannel({
            id: channel.id,
            name: channel.name,
            width: ownedOptions.width,
            height: ownedOptions.height,
            coverageStore: resampleCoverageStore(
              channel.coverageStore,
              ownedOptions.width,
              ownedOptions.height,
              ownedOptions.method,
            ),
          }),
        ),
      };
    },
  };
}

function assertFinite(value: number, name: string): void {
  if (!Number.isFinite(value)) throw new RangeError(`${name} must be finite`);
}

function assertUnit(value: number, name: string): void {
  assertFinite(value, name);
  if (value < 0 || value > 1) throw new RangeError(`${name} must be between 0 and 1`);
}

function validateLayer(layer: PixelLayer): void {
  if (!Number.isSafeInteger(layer.width) || layer.width <= 0) {
    throw new RangeError('Layer width must be a positive integer');
  }
  if (!Number.isSafeInteger(layer.height) || layer.height <= 0) {
    throw new RangeError('Layer height must be a positive integer');
  }
  if (layer.pixelStore.width !== layer.width || layer.pixelStore.height !== layer.height) {
    throw new RangeError('Layer pixel buffer length does not match its dimensions');
  }
  validateTransform(layer.transform);
}

function validateSelection(selection: SelectionMask | null | undefined): void {
  if (selection == null) return;
  if (!Number.isSafeInteger(selection.width) || selection.width <= 0) {
    throw new RangeError('Selection width must be a positive integer');
  }
  if (!Number.isSafeInteger(selection.height) || selection.height <= 0) {
    throw new RangeError('Selection height must be a positive integer');
  }
  if (
    selection.coverageStore.width !== selection.width ||
    selection.coverageStore.height !== selection.height
  ) {
    throw new RangeError('Selection coverage length does not match its dimensions');
  }
}

function validateRasterMask(mask: RasterMask): void {
  if (!Number.isSafeInteger(mask.width) || mask.width <= 0) {
    throw new RangeError('Mask width must be a positive integer');
  }
  if (!Number.isSafeInteger(mask.height) || mask.height <= 0) {
    throw new RangeError('Mask height must be a positive integer');
  }
  if (
    !(mask.coverageStore instanceof TiledCoverageStore) ||
    mask.coverageStore.width !== mask.width ||
    mask.coverageStore.height !== mask.height
  ) {
    throw new RangeError('Mask coverage length does not match its dimensions');
  }
  assertUnit(mask.density, 'Mask density');
}

function validateTransform(transform: LayerTransform): void {
  for (const component of ['a', 'b', 'c', 'd', 'e', 'f'] as const) {
    assertFinite(transform[component], `Layer transform ${component}`);
  }
  const determinant = transform.a * transform.d - transform.b * transform.c;
  if (!Number.isFinite(determinant) || determinant === 0) {
    throw new RangeError('Layer transform must be invertible');
  }
  const inverseComponents = [
    transform.d / determinant,
    -transform.b / determinant,
    -transform.c / determinant,
    transform.a / determinant,
    (transform.c * transform.f - transform.d * transform.e) / determinant,
    (transform.b * transform.e - transform.a * transform.f) / determinant,
  ];
  if (inverseComponents.some((component) => !Number.isFinite(component))) {
    throw new RangeError('Layer transform must be invertible');
  }
}

interface Point {
  readonly x: number;
  readonly y: number;
}

function transformPoint(transform: LayerTransform, x: number, y: number): Point {
  return {
    x: transform.a * x + transform.c * y + transform.e,
    y: transform.b * x + transform.d * y + transform.f,
  };
}

function invertTransform(transform: LayerTransform): LayerTransform {
  const determinant = transform.a * transform.d - transform.b * transform.c;
  return {
    a: transform.d / determinant,
    b: -transform.b / determinant,
    c: -transform.c / determinant,
    d: transform.a / determinant,
    e: (transform.c * transform.f - transform.d * transform.e) / determinant,
    f: (transform.b * transform.e - transform.a * transform.f) / determinant,
  };
}

function selectionCoverage(
  selection: SelectionMask | null | undefined,
  documentX: number,
  documentY: number,
  regionBuffer?: Uint8ClampedArray | null,
  region?: Bounds | null,
): number {
  if (selection == null) return 1;
  const sampleX = Math.floor(documentX);
  const sampleY = Math.floor(documentY);
  if (sampleX < 0 || sampleY < 0 || sampleX >= selection.width || sampleY >= selection.height) {
    return 0;
  }
  if (regionBuffer && region) {
    const localX = sampleX - region.left;
    const localY = sampleY - region.top;
    if (
      localX < 0 ||
      localY < 0 ||
      localX > region.right - region.left ||
      localY > region.bottom - region.top
    ) {
      return 0;
    }
    const width = region.right - region.left + 1;
    return (regionBuffer[localY * width + localX] ?? 0) / 255;
  }
  // Single-pixel sparse sample; avoids full-document densify for isolated queries.
  const sample = selection.coverageStore.read({ x: sampleX, y: sampleY, width: 1, height: 1 });
  const value = sample[0];
  return (typeof value === 'number' ? value : 0) / 255;
}

function unionBounds(left: Bounds | null, right: Bounds): Bounds {
  if (left === null) return { ...right };
  return {
    left: Math.min(left.left, right.left),
    top: Math.min(left.top, right.top),
    right: Math.max(left.right, right.right),
    bottom: Math.max(left.bottom, right.bottom),
  };
}

function documentDabBounds(
  documentX: number,
  documentY: number,
  radius: number,
  canvasWidth: number,
  canvasHeight: number,
): Bounds {
  return {
    left: Math.max(0, Math.floor(documentX - radius)),
    top: Math.max(0, Math.floor(documentY - radius)),
    right: Math.min(canvasWidth - 1, Math.ceil(documentX + radius)),
    bottom: Math.min(canvasHeight - 1, Math.ceil(documentY + radius)),
  };
}

function readSelectionRegion(
  selection: SelectionMask | null | undefined,
  dabs: readonly { x: number; y: number }[],
  radius: number,
): { buffer: Uint8ClampedArray | null; region: Bounds | null } {
  if (selection == null || dabs.length === 0) return { buffer: null, region: null };
  let bounds: Bounds | null = null;
  for (const dab of dabs) {
    bounds = unionBounds(
      bounds,
      documentDabBounds(dab.x, dab.y, radius, selection.width, selection.height),
    );
  }
  if (bounds === null || bounds.right < bounds.left || bounds.bottom < bounds.top) {
    return { buffer: null, region: null };
  }
  const width = bounds.right - bounds.left + 1;
  const height = bounds.bottom - bounds.top + 1;
  return {
    buffer: selection.coverageStore.read({
      x: bounds.left,
      y: bounds.top,
      width,
      height,
    }),
    region: bounds,
  };
}

function makePatchFromRegion(
  regionLeft: number,
  regionTop: number,
  regionWidth: number,
  pixels: Uint8ClampedArray,
  bounds: Bounds | null,
): PixelPatch {
  if (bounds === null) return emptyPatch();
  const width = bounds.right - bounds.left + 1;
  const height = bounds.bottom - bounds.top + 1;
  const patchPixels = new Uint8ClampedArray(width * height * 4);
  for (let row = 0; row < height; row += 1) {
    const sourceY = bounds.top - regionTop + row;
    const sourceStart = (sourceY * regionWidth + (bounds.left - regionLeft)) * 4;
    patchPixels.set(pixels.subarray(sourceStart, sourceStart + width * 4), row * width * 4);
  }
  return { x: bounds.left, y: bounds.top, width, height, pixels: patchPixels };
}

function makeCoveragePatchFromRegion(
  regionLeft: number,
  regionTop: number,
  regionWidth: number,
  coverage: Uint8ClampedArray,
  bounds: Bounds | null,
): CoveragePatch {
  if (bounds === null) return emptyCoveragePatch();
  const width = bounds.right - bounds.left + 1;
  const height = bounds.bottom - bounds.top + 1;
  const patchCoverage = new Uint8ClampedArray(width * height);
  for (let row = 0; row < height; row += 1) {
    const sourceY = bounds.top - regionTop + row;
    const sourceStart = sourceY * regionWidth + (bounds.left - regionLeft);
    patchCoverage.set(coverage.subarray(sourceStart, sourceStart + width), row * width);
  }
  return { x: bounds.left, y: bounds.top, width, height, coverage: patchCoverage };
}

function localDabBounds(
  transform: LayerTransform,
  inverse: LayerTransform,
  documentX: number,
  documentY: number,
  radius: number,
  width: number,
  height: number,
): Bounds {
  const center = transformPoint(inverse, documentX, documentY);
  // The inverse linear rows project a document-space circle into a local-space ellipse.
  // Their Euclidean lengths give tight axis-aligned extents for that ellipse.
  const extentX = radius * Math.hypot(inverse.a, inverse.c);
  const extentY = radius * Math.hypot(inverse.b, inverse.d);
  return {
    left: Math.max(0, Math.ceil(center.x - extentX)),
    top: Math.max(0, Math.ceil(center.y - extentY)),
    right: Math.min(width - 1, Math.floor(center.x + extentX)),
    bottom: Math.min(height - 1, Math.floor(center.y + extentY)),
  };
}

function emptyPatch(): PixelPatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

function emptyCoveragePatch(): CoveragePatch {
  return { x: 0, y: 0, width: 0, height: 0, coverage: new Uint8ClampedArray() };
}

function include(bounds: Bounds | null, x: number, y: number): Bounds {
  if (bounds === null) return { left: x, top: y, right: x, bottom: y };
  bounds.left = Math.min(bounds.left, x);
  bounds.top = Math.min(bounds.top, y);
  bounds.right = Math.max(bounds.right, x);
  bounds.bottom = Math.max(bounds.bottom, y);
  return bounds;
}

function compositeSourceOver(
  pixels: Uint8ClampedArray,
  offset: number,
  color: readonly [number, number, number, number],
  coverage: number,
): void {
  const sourceAlpha = (color[3] / 255) * coverage;
  const destinationAlpha = (pixels[offset + 3] ?? 0) / 255;
  const outputAlpha = sourceAlpha + destinationAlpha * (1 - sourceAlpha);
  if (outputAlpha === 0) return;
  for (let channel = 0; channel < 3; channel += 1) {
    const source = color[channel] ?? 0;
    const destination = pixels[offset + channel] ?? 0;
    pixels[offset + channel] = Math.round(
      (source * sourceAlpha + destination * destinationAlpha * (1 - sourceAlpha)) / outputAlpha,
    );
  }
  pixels[offset + 3] = Math.round(outputAlpha * 255);
}

function dabCoverage(distance: number, radius: number, hardness: number): number {
  if (distance > radius) return 0;
  const hardRadius = radius * hardness;
  if (distance <= hardRadius || hardRadius === radius) return 1;
  return 1 - (distance - hardRadius) / (radius - hardRadius);
}

/**
 * Paints a deterministic mask stroke in document space and returns the smallest mask-local
 * coverage patch containing changed samples. The input mask and its coverage remain untouched.
 */
export function paintMaskStroke(
  mask: RasterMask,
  layerTransform: LayerTransform,
  points: readonly BrushPoint[],
  options: MaskBrushOptions,
  selection?: SelectionMask | null,
): CoveragePatch {
  validateRasterMask(mask);
  validateTransform(layerTransform);
  validateSelection(selection);
  assertFinite(options.size, 'Mask brush size');
  if (options.size < 0) throw new RangeError('Mask brush size must be at least 0');
  assertUnit(options.hardness, 'Mask brush hardness');
  assertUnit(options.opacity, 'Mask brush opacity');
  const mode: unknown = options.mode;
  if (mode !== 'reveal' && mode !== 'conceal') {
    throw new RangeError('Mask brush mode must be reveal or conceal');
  }
  for (const [index, point] of points.entries()) {
    assertFinite(point.x, `Mask stroke point ${String(index)} x`);
    assertFinite(point.y, `Mask stroke point ${String(index)} y`);
    assertUnit(point.pressure ?? 1, `Mask stroke point ${String(index)} pressure`);
  }
  if (points.length === 0 || options.size === 0 || options.opacity === 0) {
    return emptyCoveragePatch();
  }

  const radius = options.size / 2;
  const inverse = invertTransform(layerTransform);
  const spacing = Math.max(0.25, radius * 0.5);
  const first = points[0];
  const dabs: Array<{ x: number; y: number; pressure: number }> = [
    { x: first.x, y: first.y, pressure: first.pressure ?? 1 },
  ];
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Stroke working set: union of local dab bounds only (no full-mask densify).
  let strokeBounds: Bounds | null = null;
  for (const dab of dabs) {
    strokeBounds = unionBounds(
      strokeBounds,
      localDabBounds(layerTransform, inverse, dab.x, dab.y, radius, mask.width, mask.height),
    );
  }
  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
    return emptyCoveragePatch();
  }
  const regionLeft = strokeBounds.left;
  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const next = mask.coverageStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs, radius);
  let changedBounds: Bounds | null = null;

  for (const dab of dabs) {
    const bounds = localDabBounds(
      layerTransform,
      inverse,
      dab.x,
      dab.y,
      radius,
      mask.width,
      mask.height,
    );
    const { left, top, right, bottom } = bounds;
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) {
        const documentPoint = transformPoint(layerTransform, x, y);
        const falloff = dabCoverage(
          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
          radius,
          options.hardness,
        );
        const selected = selectionCoverage(
          selection,
          documentPoint.x,
          documentPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const strength = falloff * options.opacity * dab.pressure * selected;
        if (strength <= 0) continue;
        const offset = (y - regionTop) * regionWidth + (x - regionLeft);
        const original = next[offset] ?? 0;
        const target = options.mode === 'reveal' ? 255 : 0;
        const value = Math.round(original + (target - original) * strength);
        if (value === original) continue;
        next[offset] = value;
        changedBounds = include(changedBounds, x, y);
      }
    }
  }

  return makeCoveragePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

