    }
  }
  return result;
}

function destinationTileKeys(
  sourceTiles: Iterable<{ x: number; y: number; width: number; height: number }>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  destinationTileSize: number,
