    expect(result.read({ x: size - 1, y: size - 1, width: 1, height: 1 })).toEqual(
      new Uint8ClampedArray([55, 95, 135, 200]),
    );
    expect(store.read({ x: 0, y: 0, width: 1, height: 1 })).toEqual(
      new Uint8ClampedArray([40, 80, 120, 200]),
    );
