    kind: 'pixel',
    id: options.id,
    name: options.name,
    width: options.width,
    height: options.height,
    pixelStore,
    ...layerBase(options),
    rasterMask: copyRasterMask(options.rasterMask),
    vectorMask: copyVectorMask(options.vectorMask),
  };
  validateLayers([layer]);
  return layer;
