  assertName(options.name, 'Layer name');
  const group: GroupLayer = {
    kind: 'group',
    id: options.id,
    name: options.name,
    children: (options.children ?? []).map(copyLayer),
    ...layerBase(options),
    compositing: options.compositing ?? 'pass-through',
