    const deltaX = point.x - owned.x;
    const deltaY = point.y - owned.y;
    commands[commandIndex] =
      owned.type === 'cubic'
        ? {
            ...owned,
            x: point.x,
            y: point.y,
            control2X: owned.control2X + deltaX,
            control2Y: owned.control2Y + deltaY,
