  }, [selectedLayerId, selectedMask?.density]);

  useEffect(() => {
    if (selectedMask === null) setEditTarget('pixels');
    else if (selectedLayer && selectedLayer.kind !== 'pixel' && selectedLayer.kind !== 'adjustment')
      setEditTarget('mask');
