        setChannelView('composite');
        setCropRectangle(null);
        setSelectionPreview(null);
        setSelectionMaskPreview(null);
        setLassoPreview([]);
        setSizeDialog(null);
        setSaveState('saved');
        requestAnimationFrame(() => fitTarget(restored));
