function applyGuideSnap(
  point: DocumentPoint,
  viewport: ViewportTransform,
  snap: GuideSnapContext | undefined,
): DocumentPoint {
  if (!snap?.enabled || !snap.document) {
    if (snap?.activeSmartEdgesSink) snap.activeSmartEdgesSink.current = [];
