    {
      id: 'image.size',
      label: 'Image Size…',
      menu: 'image',
      shortcut: 'Ctrl+Alt+I',
      enabled: Boolean(document) && !busy,
      execute: () => openImageSize(),
    },
    {
      id: 'image.canvas-size',
