    {
      id: 'layer.delete',
      label: 'Delete Layer',
      menu: 'layer',
      enabled: selectedLayerIds.length > 0,
      execute: deleteSelectedLayer,
    },
    {
      id: 'layer.flatten',
      label: 'Flatten Image',
      menu: 'layer',
      enabled: Boolean(document?.layers.length),
      execute: flattenImage,
    },
    {
      id: 'type.new',
      label: 'New Text Layer',
      menu: 'type',
      shortcut: 'T',
      enabled: Boolean(document),
