          setLayerTransform(
            transformOverlay.layer.id,
            transformAroundLayerCenter(transformOverlay.layer, {
              a: Math.cos(radians),
              b: Math.sin(radians),
              c: -Math.sin(radians),
              d: Math.cos(radians),
              e: 0,
