      const height = Math.min(160, document.canvas.height);
      const layer = createShapeLayer({
        id: makeId('shape'),
        name: type === 'rectangle' ? 'Rectangle' : 'Ellipse',
        geometry: { type, width, height, cornerRadius: 0 },
        transform: {
          ...identityLayerTransform(),
