    const destLocal = transformPoint(destInverse, destDocX, destDocY);
    const srcLocal = transformPoint(srcInverse, srcDocX, srcDocY);

    // Accumulate bounds for destination layer
    if (!strokeBounds) {
      strokeBounds = {
        left: Math.floor(destLocal.x - radius),
        top: Math.floor(destLocal.y - radius),
        right: Math.ceil(destLocal.x + radius),
        bottom: Math.ceil(destLocal.y + radius),
      };
    } else {
      strokeBounds.left = Math.min(strokeBounds.left, Math.floor(destLocal.x - radius));
      strokeBounds.top = Math.min(strokeBounds.top, Math.floor(destLocal.y - radius));
      strokeBounds.right = Math.max(strokeBounds.right, Math.ceil(destLocal.x + radius));
      strokeBounds.bottom = Math.max(strokeBounds.bottom, Math.ceil(destLocal.y + radius));
    }
  }

  if (!strokeBounds) {
    return emptyPatch();
  }

  // Clip bounds to destination layer
  strokeBounds.left = Math.max(0, strokeBounds.left);
  strokeBounds.top = Math.max(0, strokeBounds.top);
  strokeBounds.right = Math.min(destinationLayer.width - 1, strokeBounds.right);
  strokeBounds.bottom = Math.min(destinationLayer.height - 1, strokeBounds.bottom);

  if (strokeBounds.left > strokeBounds.right || strokeBounds.top > strokeBounds.bottom) {
    return emptyPatch();
  }

