      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = destPixels[srcOffset];
      patchPixels[dstOffset + 1] = destPixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = destPixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = destPixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

