  }

  const radius = size / 2;

  // Build interpolated dabs
  const dabs = buildDabs(points, radius);

  // Calculate source-to-destination offset for aligned mode
  // In aligned mode, we track the offset from the initial source point to the first destination point
  let alignedOffset: { x: number; y: number } | null = null;
