function invertTransform(transform: LayerTransform): LayerTransform {
  const det = transform.a * transform.d - transform.b * transform.c;
  if (det === 0) {
    throw new RangeError('Transform is not invertible');
  }
  return {
    a: transform.d / det,
    b: -transform.b / det,
    c: -transform.c / det,
    d: transform.a / det,
    e: (transform.c * transform.f - transform.d * transform.e) / det,
    f: (transform.b * transform.e - transform.a * transform.f) / det,
  };
}

function transformPoint(transform: LayerTransform, x: number, y: number): { x: number; y: number } {
  return {
    x: transform.a * x + transform.c * y + transform.e,
    y: transform.b * x + transform.d * y + transform.f,
  };
}

function emptyPatch(): PixelPatch {
  return {
    x: 0,
    y: 0,
    width: 0,
    height: 0,
    pixels: new Uint8ClampedArray(0),
  };
}

