      }
    } else {
      // Aligned: source = destination + offset (or destination if no offset)
      sourceDocPoint = { ...dab };
      if (source.offset !== null) {
        sourceDocPoint = {
          x: sourceDocPoint.x + source.offset.x,
          y: sourceDocPoint.y + source.offset.y,
