    const sparse = TiledCoverageStore.empty(64, 64).write({
      x: 8,
      y: 8,
      width: 4,
      height: 4,
      coverage: new Uint8ClampedArray(16).fill(255),
    }).store;
    const denseReference = resampleCoverage(sparse.toContiguous(), 64, 64, 32, 32, 'nearest');
    const sparseResult = resampleCoverageStore(sparse, 32, 32, 'nearest');
    expect(sparseResult.toContiguous()).toEqual(denseReference);
    // Sparse result may allocate one tile (≤ dest canvas) but not more than dense full buffer.
    expect(sparseResult.allocatedByteLength).toBeLessThanOrEqual(32 * 32);
    expect(sparseResult.tileCount).toBeGreaterThan(0);
    expect(sparseResult.tileCount).toBeLessThanOrEqual(4);
  });

  it('resamples sparse complement coverage without allocating its full destination', () => {
    const complement = TiledCoverageStore.uniform(4096, 4096, 255, 256).write({
      x: 1024,
      y: 2048,
      width: 16,
      height: 8,
      coverage: new Uint8ClampedArray(16 * 8),
    }).store;
    const materialize = vi.spyOn(complement, 'toContiguous');
    const resized = resampleCoverageStore(complement, 2048, 2048, 'nearest');
    expect(materialize).not.toHaveBeenCalled();
    expect(resized).toMatchObject({
      defaultCoverage: 255,
      tileCount: 1,
      allocatedByteLength: 256 * 256,
    });
    expect(resized.read({ x: 512, y: 1024, width: 1, height: 1 })[0]).toBe(0);
    expect(resized.read({ x: 0, y: 0, width: 1, height: 1 })[0]).toBe(255);
  });

  it('resamples sparse pixel stores without densifying empty layers', () => {
    const empty = TiledPixelStore.empty(128, 128);
    const resizedEmpty = resamplePixelStore(empty, 64, 64, 'nearest');
    expect(resizedEmpty.tileCount).toBe(0);

    const pixels = new Uint8ClampedArray(8 * 8 * 4);
    for (let offset = 0; offset < pixels.length; offset += 4) {
      pixels[offset] = 200;
      pixels[offset + 1] = 10;
      pixels[offset + 2] = 20;
      pixels[offset + 3] = 255;
    }
    const sparse = TiledPixelStore.empty(128, 128).write({
      x: 16,
      y: 24,
      width: 8,
      height: 8,
      pixels,
    }).store;
    const denseReference = resamplePixels(sparse.toContiguous(), 128, 128, 64, 64, 'nearest');
    const sparseResult = resamplePixelStore(sparse, 64, 64, 'nearest');
    expect(sparseResult.toContiguous()).toEqual(denseReference);
    // Sparse path may use one dest tile (≤ full canvas bytes) but stays bounded.
    expect(sparseResult.allocatedByteLength).toBeLessThanOrEqual(64 * 64 * 4);
    expect(sparseResult.tileCount).toBeGreaterThan(0);
    expect(sparseResult.tileCount).toBeLessThanOrEqual(4);
  });

  it('resizes distant 8192² pixel and coverage tiles without a full-span read', () => {
    const size = 8192;
    const tileSize = 64;
    const far = size - tileSize;
    const coverageTile = new Uint8ClampedArray(tileSize * tileSize).fill(255);
    const pixelTile = new Uint8ClampedArray(tileSize * tileSize * 4).fill(120);
    let coverageStore = TiledCoverageStore.empty(size, size, tileSize);
    let pixelStore = TiledPixelStore.empty(size, size, tileSize);
    for (const position of [0, far]) {
      coverageStore = coverageStore.write({
        x: position,
        y: position,
        width: tileSize,
        height: tileSize,
        coverage: coverageTile,
      }).store;
      pixelStore = pixelStore.write({
        x: position,
        y: position,
        width: tileSize,
        height: tileSize,
        pixels: pixelTile,
      }).store;
    }
    const pixelRead = vi.spyOn(TiledPixelStore.prototype, 'read');
    const coverageRead = vi.spyOn(TiledCoverageStore.prototype, 'read');
    const pixelDense = vi.spyOn(TiledPixelStore.prototype, 'toContiguous');
    const coverageDense = vi.spyOn(TiledCoverageStore.prototype, 'toContiguous');
    const resized = resizeImage({ width: size / 2, height: size / 2, method: 'nearest' }).execute(
      createDocument({
        id: 'sparse-resize-document',
        name: 'Sparse resize document',
        width: size,
        height: size,
        selection: createSelectionMask({ width: size, height: size, coverageStore }),
        channels: [
          createAlphaChannel({
            id: 'alpha',
            name: 'Alpha',
            width: size,
            height: size,
            coverageStore,
          }),
        ],
        layers: [
          createPixelLayer({
            id: 'pixels',
            name: 'Pixels',
            width: size,
            height: size,
            pixelStore,
            rasterMask: createRasterMaskFromCoverageStore(size, size, coverageStore),
          }),
        ],
      }),
    );
    expect(pixelRead).not.toHaveBeenCalled();
    expect(coverageRead).not.toHaveBeenCalled();
    expect(pixelDense).not.toHaveBeenCalled();
    expect(coverageDense).not.toHaveBeenCalled();
    const layer = resized.layers[0];
    if (layer?.kind !== 'pixel') throw new Error('Expected resized pixel layer');
    expect(layer.pixelStore.tileCount).toBe(2);
    expect(layer.pixelStore.allocatedByteLength).toBe(2 * tileSize * tileSize * 4);
    expect(layer.rasterMask?.coverageStore.tileCount).toBe(2);
    expect(resized.selection?.coverageStore.tileCount).toBe(2);
    expect(resized.channels[0]?.coverageStore.tileCount).toBe(2);
    expect(layer.pixelStore.getTile(0, 0)?.pixels[3]).toBe(120);
    expect(layer.pixelStore.getTile(63, 63)?.pixels[(32 * tileSize + 32) * 4 + 3]).toBe(120);
  });

  it('keeps sparse tiled bilinear output pixel-equivalent to the dense reference', () => {
    const coverage = TiledCoverageStore.empty(32, 32, 8)
      .write({
        x: 0,
        y: 0,
        width: 2,
        height: 2,
        coverage: new Uint8ClampedArray([64, 128, 192, 255]),
      })
      .store.write({
        x: 30,
        y: 30,
        width: 2,
        height: 2,
        coverage: new Uint8ClampedArray([255, 192, 128, 64]),
      }).store;
    const pixels = new Uint8ClampedArray(2 * 2 * 4).fill(160);
    const pixelStore = TiledPixelStore.empty(32, 32, 8)
      .write({ x: 0, y: 0, width: 2, height: 2, pixels })
      .store.write({ x: 30, y: 30, width: 2, height: 2, pixels }).store;
    expect(resampleCoverageStore(coverage, 19, 17, 'bilinear').toContiguous()).toEqual(
      resampleCoverage(coverage.toContiguous(), 32, 32, 19, 17, 'bilinear'),
    );
    expect(resamplePixelStore(pixelStore, 19, 17, 'bilinear').toContiguous()).toEqual(
      resamplePixels(pixelStore.toContiguous(), 32, 32, 19, 17, 'bilinear'),
    );
  });

  it('resamples coverage with nearest and bilinear pixel-center sampling', () => {
    expect(Array.from(resampleCoverage([0, 255], 2, 1, 4, 1, 'nearest'))).toEqual([0, 0, 255, 255]);
    expect(Array.from(resampleCoverage([0, 255], 2, 1, 3, 1, 'bilinear'))).toEqual([0, 128, 255]);
  });

  it('interpolates RGBA in premultiplied alpha to avoid transparent color fringes', () => {
    const resized = resamplePixels([255, 0, 0, 255, 0, 0, 255, 0], 2, 1, 3, 1, 'bilinear');
    expect(Array.from(resized)).toEqual([255, 0, 0, 255, 255, 0, 0, 128, 0, 0, 0, 0]);
  });

  it('replicates exact nearest-neighbor quadrants when enlarging', () => {
    const source = [255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255];
    const resized = resamplePixels(source, 2, 2, 4, 4, 'nearest');
    const pixel = (x: number, y: number) =>
      Array.from(resized.slice((y * 4 + x) * 4, (y * 4 + x + 1) * 4));
    expect(pixel(0, 0)).toEqual([255, 0, 0, 255]);
    expect(pixel(3, 0)).toEqual([0, 255, 0, 255]);
    expect(pixel(0, 3)).toEqual([0, 0, 255, 255]);
    expect(pixel(3, 3)).toEqual([255, 255, 0, 255]);
  });

  it('resizes nested layers, masks, selections, and channels without changing prior state', () => {
    const pixels = new Uint8ClampedArray([
      255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255,
    ]);
    const document = createDocument({
      id: 'doc',
      name: 'Resize',
      width: 4,
      height: 4,
      selection: createSelectionMask({
        width: 4,
        height: 4,
        coverage: new Uint8ClampedArray([0, 0, 0, 0, 0, 255, 255, 0, 0, 255, 255, 0, 0, 0, 0, 0]),
      }),
      channels: [
        createAlphaChannel({
          id: 'alpha',
          name: 'Alpha',
          width: 4,
          height: 4,
          coverage: new Uint8ClampedArray(16).fill(255),
        }),
      ],
      layers: [
        createGroupLayer({
          id: 'group',
          name: 'Group',
          transform: { ...identity, e: 1, f: 1 },
          rasterMask: createRasterMask(4, 4, new Uint8ClampedArray(16).fill(192)),
          vectorMask: createVectorMask(4, 4, [
            { type: 'move', x: 0, y: 0 },
            { type: 'line', x: 2, y: 0 },
            { type: 'line', x: 2, y: 4 },
            { type: 'close' },
          ]),
          children: [
            createPixelLayer({
              id: 'pixel',
              name: 'Pixel',
              width: 2,
              height: 2,
              pixels,
              transform: { a: 0, b: 1, c: -1, d: 0, e: 2, f: 0 },
              rasterMask: createRasterMask(2, 2, [0, 255, 255, 0]),
              vectorMask: createVectorMask(2, 2, [
                { type: 'move', x: 0.5, y: 0.5 },
                { type: 'line', x: 1.5, y: 0.5 },
                { type: 'line', x: 1, y: 1.5 },
                { type: 'close' },
              ]),
            }),
          ],
        }),
        createAdjustmentLayer({
          id: 'adjustment',
          name: 'Adjustment',
          vectorMask: createVectorMask(4, 4, [
            { type: 'move', x: 1, y: 1 },
            { type: 'line', x: 3, y: 1 },
            { type: 'line', x: 2, y: 3 },
            { type: 'close' },
          ]),
        }),
      ],
    });
    const originalWorld = findLayerWorldTransform(document, 'pixel');
    const resized = resizeImage({ width: 8, height: 6, method: 'nearest' }).execute(document);
    const resizedLayer = findLayer(resized, 'pixel');
    const resizedWorld = findLayerWorldTransform(resized, 'pixel');

    expect(resized.canvas).toEqual({ width: 8, height: 6 });
    expect(resizedLayer).toMatchObject({ width: 4, height: 3 });
    expect(findLayer(resized, 'group')?.transform).toEqual({
      a: 2,
      b: 0,
      c: 0,
      d: 1.5,
      e: 2,
      f: 1.5,
    });
    expect(findLayer(resized, 'group')).toMatchObject({
      kind: 'group',
      vectorMask: {
        width: 8,
        height: 6,
        commands: [
          { type: 'move', x: 0, y: 0 },
          { type: 'line', x: 4, y: 0 },
          { type: 'line', x: 4, y: 6 },
          { type: 'close' },
        ],
      },
      rasterMask: { width: 8, height: 6 },
    });
    const resizedGroup = findLayer(resized, 'group');
    expect(resizedGroup?.rasterMask?.coverageStore.toContiguous()).toEqual(
      new Uint8ClampedArray(48).fill(192),
    );
    expect(resizedLayer?.transform).toEqual({
      a: 0,
      b: 0.5,
      c: -2 / 3,
      d: 0,
      e: 2,
      f: 0,
    });
    expect(resizedLayer?.kind === 'pixel' ? resizedLayer.rasterMask : null).toMatchObject({
      width: 4,
      height: 3,
    });
    expect(resizedLayer?.kind === 'pixel' ? resizedLayer.vectorMask : null).toMatchObject({
      width: 4,
      height: 3,
      commands: [
        { type: 'move', x: 1, y: 0.75 },
        { type: 'line', x: 3, y: 0.75 },
        { type: 'line', x: 2, y: 2.25 },
        { type: 'close' },
      ],
    });
    expect(findLayer(resized, 'adjustment')).toMatchObject({
      kind: 'adjustment',
      vectorMask: {
        width: 8,
        height: 6,
        commands: [
          { type: 'move', x: 2, y: 1.5 },
          { type: 'line', x: 6, y: 1.5 },
          { type: 'line', x: 4, y: 4.5 },
          { type: 'close' },
        ],
      },
    });
    expect(resized.selection).toMatchObject({ width: 8, height: 6 });
    expect(resized.channels[0]).toMatchObject({ width: 8, height: 6 });
    expect(resized.channels[0]?.coverageStore.toContiguous().length).toBe(8 * 6);
    expect(resizeImage({ width: 8, height: 6, method: 'nearest' }).label).toBe('Resize image');
    if (!originalWorld || !resizedWorld) throw new Error('Expected layer transforms');
    const originalPoint = transformPoint(originalWorld, 1, 1);
    const resizedPoint = transformPoint(resizedWorld, 2, 1.5);
    expect(resizedPoint.x).toBeCloseTo(originalPoint.x * 2);
    expect(resizedPoint.y).toBeCloseTo(originalPoint.y * 1.5);
    const originalPixelLayer = findLayer(document, 'pixel');
    expect(originalPixelLayer).toMatchObject({ width: 2, height: 2 });
    expect(
      originalPixelLayer?.kind === 'pixel'
        ? originalPixelLayer.pixelStore.toContiguous()
        : undefined,
    ).toEqual(pixels);
    expect(document.canvas).toEqual({ width: 4, height: 4 });
    expect(resizeImage({ width: 4, height: 4, method: 'nearest' }).execute(document)).toBe(
      document,
    );
  });

  it('validates methods, buffers, dimensions, and allocation limits', () => {
    expect(() => resamplePixels([0], 1, 1, 1, 1, 'nearest')).toThrow(
      'Pixel buffer length does not match',
    );
    expect(() => resampleCoverage([], 1, 1, 1, 1, 'nearest')).toThrow(
      'Coverage buffer length does not match',
    );
    expect(() => resizeImage({ width: 0, height: 1, method: 'nearest' })).toThrow(
      'Image width must be a positive integer',
    );
    expect(() => resizeImage({ width: 32_769, height: 1, method: 'nearest' })).toThrow(
      'Image dimensions cannot exceed 32768 pixels',
    );
    expect(() => resizeImage({ width: 20_000, height: 10_000, method: 'bilinear' })).toThrow(
      'Image area cannot exceed 100000000 pixels',
    );
    expect(() => resizeImage({ width: 1, height: 1, method: 'cubic' as 'nearest' })).toThrow(
      'Resampling method must be nearest or bilinear',
    );
    const layered = createDocument({
      id: 'large',
      name: 'Large',
      width: 1,
      height: 1,
      layers: ['One', 'Two', 'Three'].map((name) =>
        createPixelLayer({ id: name, name, width: 1, height: 1 }),
      ),
    });
    expect(() =>
      resizeImage({ width: 10_000, height: 10_000, method: 'nearest' }).execute(layered),
    ).toThrow('Resize working set cannot exceed 1000000000 bytes');
  });
});

import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

export type LayerId = string;

export interface LayerTransform {
  readonly a: number;
  readonly b: number;
  readonly c: number;
  readonly d: number;
  readonly e: number;
  readonly f: number;
}

export interface TransformPoint {
  readonly x: number;
  readonly y: number;
}

export const BLEND_MODES = [
  'normal',
  'multiply',
  'screen',
  'overlay',
  'darken',
  'darker-color',
  'lighten',
  'lighter-color',
  'color-dodge',
  'linear-dodge',
  'color-burn',
  'linear-burn',
  'hard-light',
  'soft-light',
  'vivid-light',
  'linear-light',
  'pin-light',
  'hard-mix',
  'difference',
  'exclusion',
  'subtract',
  'divide',
  'hue',
  'saturation',
  'color',
  'luminosity',
] as const;

export type BlendMode = (typeof BLEND_MODES)[number];
export type GroupCompositingMode = 'pass-through' | 'isolated';

export interface LayerLocks {
  readonly transparency: boolean;
  readonly pixels: boolean;
  readonly position: boolean;
  readonly all: boolean;
}

export interface ColorOverlayEffect {
  readonly type: 'color-overlay';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly blendMode: BlendMode;
  readonly color: RgbaColor;
}

export interface StrokeEffect {
  readonly type: 'stroke';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly size: number;
  readonly color: RgbaColor;
}

export interface DropShadowEffect {
  readonly type: 'drop-shadow';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly offsetX: number;
  readonly offsetY: number;
  readonly blur: number;
  readonly color: RgbaColor;
}

export type LayerEffect = ColorOverlayEffect | StrokeEffect | DropShadowEffect;

export interface LayerBase {
  readonly id: LayerId;
  readonly name: string;
  readonly visible: boolean;
  readonly opacity: number;
  readonly fillOpacity: number;
  readonly blendMode: BlendMode;
  readonly clipping: boolean;
  readonly locks: LayerLocks;
  readonly transform: LayerTransform;
  readonly effects: readonly LayerEffect[];
}

export interface PixelLayer extends LayerBase {
  readonly kind: 'pixel';
  readonly width: number;
  readonly height: number;
  /** Canonical sparse, immutable RGBA8 pixel resource. */
  readonly pixelStore: TiledPixelStore;
  readonly rasterMask: RasterMask | null;
  readonly vectorMask: VectorMask | null;
}

export interface RasterMask {
  readonly width: number;
  readonly height: number;
  /** Canonical sparse, immutable 8-bit coverage resource. */
  readonly coverageStore: TiledCoverageStore;
  readonly enabled: boolean;
  /** Normalized strength of the mask effect. */
  readonly density: number;
}

export interface VectorMask {
  readonly width: number;
  readonly height: number;
  readonly commands: readonly PathCommand[];
  readonly enabled: boolean;
  /** Normalized strength of the mask effect. */
  readonly density: number;
  readonly inverted: boolean;
}

export interface GroupLayer extends LayerBase {
  readonly kind: 'group';
  readonly children: readonly Layer[];
  readonly compositing: GroupCompositingMode;
  /** Document-space coverage applied to the group's combined result. */
  readonly rasterMask: RasterMask | null;
  /** Document-space mask applied to the group's combined result. */
  readonly vectorMask: VectorMask | null;
}

export interface BrightnessContrastAdjustment {
  readonly type: 'brightness-contrast';
  readonly brightness: number;
  readonly contrast: number;
}

export interface InvertAdjustment {
  readonly type: 'invert';
}

export interface LevelsAdjustment {
  readonly type: 'levels';
  readonly inputBlack: number;
  readonly inputWhite: number;
  readonly gamma: number;
  readonly outputBlack: number;
  readonly outputWhite: number;
}

export interface HueSaturationAdjustment {
  readonly type: 'hue-saturation';
  readonly hue: number;
  readonly saturation: number;
  readonly lightness: number;
}

export interface PosterizeAdjustment {
  readonly type: 'posterize';
  /** Integer number of tonal levels in [2, 256]. */
  readonly levels: number;
}

export interface ThresholdAdjustment {
  readonly type: 'threshold';
  /** Integer threshold level in [0, 255]. */
  readonly level: number;
}

export type Adjustment =
  | BrightnessContrastAdjustment
  | InvertAdjustment
  | LevelsAdjustment
  | HueSaturationAdjustment
  | PosterizeAdjustment
  | ThresholdAdjustment;

export interface AdjustmentLayer extends LayerBase {
  readonly kind: 'adjustment';
  readonly adjustment: Adjustment;
  /** Document-space mask. Null applies the adjustment everywhere. */
  readonly rasterMask: RasterMask | null;
  readonly vectorMask: VectorMask | null;
}

export interface RgbaColor {
  readonly red: number;
  readonly green: number;
  readonly blue: number;
  readonly alpha: number;
}

export const SHAPE_KINDS = ['rectangle', 'ellipse', 'path'] as const;
export type ShapeKind = (typeof SHAPE_KINDS)[number];

export type PathCommand =
  | { readonly type: 'move'; readonly x: number; readonly y: number }
  | { readonly type: 'line'; readonly x: number; readonly y: number }
  | {
      readonly type: 'cubic';
      readonly control1X: number;
      readonly control1Y: number;
      readonly control2X: number;
      readonly control2Y: number;
      readonly x: number;
      readonly y: number;
    }
  | { readonly type: 'close' };

export interface ShapeGeometry {
  readonly type: ShapeKind;
  readonly width: number;
  readonly height: number;
  readonly cornerRadius: number;
  readonly commands: readonly PathCommand[];
}

export interface ShapeStyle {
  readonly fill: RgbaColor | null;
  readonly stroke: RgbaColor | null;
  readonly strokeWidth: number;
}

export interface ShapeLayer extends LayerBase {
  readonly kind: 'shape';
  readonly geometry: ShapeGeometry;
  readonly style: ShapeStyle;
  readonly rasterMask: RasterMask | null;
  readonly vectorMask: VectorMask | null;
}

export const TEXT_ALIGNMENTS = ['left', 'center', 'right'] as const;
export type TextAlign = (typeof TEXT_ALIGNMENTS)[number];

export interface TextStyle {
  readonly fontFamily: string;
  readonly fontSize: number;
  readonly fontWeight: number;
  readonly italic: boolean;
  readonly lineHeight: number;
  readonly align: TextAlign;
  readonly color: RgbaColor;
}

export interface TextLayer extends LayerBase {
  readonly kind: 'text';
  readonly text: string;
  readonly width: number;
  readonly height: number;
  readonly style: TextStyle;
  readonly rasterMask: RasterMask | null;
  readonly vectorMask: VectorMask | null;
}

export interface SmartObjectSource {
  readonly id: string;
  readonly name: string;
  readonly canvas: DocumentCanvas;
  readonly layers: readonly Layer[];
}

interface SmartFilterBase {
  readonly id: string;
  readonly enabled: boolean;
  readonly opacity: number;
}

export interface SmartInvertFilter extends SmartFilterBase {
  readonly type: 'invert';
}

export interface SmartGrayscaleFilter extends SmartFilterBase {
  readonly type: 'grayscale';
}

export interface SmartGaussianBlurFilter extends SmartFilterBase {
  readonly type: 'gaussian-blur';
  readonly radius: number;
}

export interface SmartBrightnessContrastFilter extends SmartFilterBase {
  readonly type: 'brightness-contrast';
  readonly brightness: number;
  readonly contrast: number;
}

export type SmartFilter =
  | SmartInvertFilter
  | SmartGrayscaleFilter
  | SmartGaussianBlurFilter
  | SmartBrightnessContrastFilter;

export interface SmartObjectLayer extends LayerBase {
  readonly kind: 'smart-object';
  readonly source: SmartObjectSource;
  readonly smartFilters: readonly SmartFilter[];
  readonly rasterMask: RasterMask | null;
  readonly vectorMask: VectorMask | null;
}

export type Layer =
  | PixelLayer
  | GroupLayer
  | AdjustmentLayer
  | ShapeLayer
  | TextLayer
  | SmartObjectLayer;

export interface DocumentCanvas {
  readonly width: number;
  readonly height: number;
}

/** Document guide orientation in canvas space. */
export type GuideDirection = 'horizontal' | 'vertical';

/**
 * A single ruler guide. `position` is in document pixels from the top (horizontal
 * guides) or left (vertical guides) edge of the canvas.
 */
export interface DocumentGuide {
  readonly id: string;
  readonly direction: GuideDirection;
  readonly position: number;
}

/** Optional document grid spacing in canvas pixels (Photoshop-style). */
export interface DocumentGrid {
  readonly horizontal: number;
  readonly vertical: number;
}

/**
 * Document-level work path / saved path (not a layer). Geometry is in document
 * canvas coordinates using the same PathCommand vocabulary as shape layers.
 */
export interface DocumentPath {
  readonly id: string;
  readonly name: string;
  /** True when the path is open (not a closed subpath). */
  readonly open: boolean;
  readonly commands: readonly PathCommand[];
}

/**
 * Opaque import/export preservation bag. Must be JSON-serializable.
 * Engines must not interpret unknown keys; persistence may round-trip them.
 */
export type DocumentPreservation = Readonly<Record<string, unknown>>;

export interface ImageDocument {
  readonly id: string;
  readonly name: string;
  readonly canvas: DocumentCanvas;
  readonly layers: readonly Layer[];
  /** Full-resolution 8-bit coverage; null means the entire canvas is selected. */
  readonly selection: SelectionMask | null;
  /** Saved full-resolution 8-bit alpha channels in document coordinates. */
  readonly channels: readonly AlphaChannel[];
  /** Ruler guides in document coordinates (may be empty). */
  readonly guides: readonly DocumentGuide[];
  /** Optional document grid; null when no grid is defined. */
  readonly grid: DocumentGrid | null;
  /** Document-level paths (work path / saved paths); may be empty. */
  readonly paths: readonly DocumentPath[];
  /**
   * Optional opaque payload preserved across save/reopen (e.g. PSD unsupported
   * layer records). Omitted or null when no preservation data is attached.
   */
  readonly preservation?: DocumentPreservation | null;
}

export interface SelectionMask {
  readonly width: number;
  readonly height: number;
  /** Canonical sparse coverage ownership. Contiguous views are algorithm-boundary only. */
  readonly coverageStore: TiledCoverageStore;
}

export interface AlphaChannel {
  readonly id: string;
  readonly name: string;
  readonly width: number;
  readonly height: number;
  /** Canonical sparse coverage ownership. Contiguous views are algorithm-boundary only. */
  readonly coverageStore: TiledCoverageStore;
}

/** Builds a selection that owns a sparse coverage store from dense input. */
export function createSelectionMask(options: {
  readonly width: number;
  readonly height: number;
  readonly coverage?: ArrayLike<number>;
  readonly coverageStore?: TiledCoverageStore;
}): SelectionMask {
  assertPositiveInteger(options.width, 'Selection width');
  assertPositiveInteger(options.height, 'Selection height');
  if (options.coverageStore !== undefined) {
    if (
      !(options.coverageStore instanceof TiledCoverageStore) ||
      options.coverageStore.width !== options.width ||
      options.coverageStore.height !== options.height
    ) {
      throw new DocumentInvariantError('Selection coverage store must match its dimensions');
    }
    return {
      width: options.width,
      height: options.height,
      coverageStore: options.coverageStore,
    };
  }
  const expectedLength = options.width * options.height;
  const coverage =
    options.coverage === undefined
      ? new Uint8ClampedArray(expectedLength)
      : new Uint8ClampedArray(options.coverage);
  if (coverage.length !== expectedLength) {
    throw new DocumentInvariantError(
      `Selection coverage must contain ${String(expectedLength)} values`,
    );
  }
  return {
    width: options.width,
    height: options.height,
    coverageStore: TiledCoverageStore.fromContiguous(options.width, options.height, coverage),
  };
}

/**
 * Explicit compatibility materialization for algorithms that still require dense coverage.
 * Ordinary ownership, copy, history, and transport paths must not call this.
 */
export function materializeSelectionCoverage(selection: SelectionMask): Uint8ClampedArray {
  if (
    !(selection.coverageStore instanceof TiledCoverageStore) ||
    selection.coverageStore.width !== selection.width ||
    selection.coverageStore.height !== selection.height
  ) {
    throw new DocumentInvariantError('Selection coverage store must match its dimensions');
  }
  return selection.coverageStore.toContiguous();
}

/**
 * Explicit compatibility materialization for algorithms that still require dense channel coverage.
 */
export function materializeAlphaChannelCoverage(channel: AlphaChannel): Uint8ClampedArray {
  if (
    !(channel.coverageStore instanceof TiledCoverageStore) ||
    channel.coverageStore.width !== channel.width ||
    channel.coverageStore.height !== channel.height
  ) {
    throw new DocumentInvariantError(
      `Alpha channel coverage store must match its dimensions: ${channel.id}`,
    );
  }
  return channel.coverageStore.toContiguous();
}

