export const NEW_DOCUMENT_SIZE = { width: 1024, height: 768 } as const;
export const MAX_DOCUMENT_DIMENSION = 32_768;
export const MAX_DOCUMENT_PIXELS = 100_000_000;

export function makeId(prefix: string): string {
