            trigger && window.document.contains(trigger)
              ? trigger
              : window.document.getElementById('menu-image');
          target?.focus();
        }, 100);
      });
    });
  }, []);

  const openCanvasSize = useCallback(
    (trigger?: HTMLButtonElement) => {
