      setChannelView('composite');
      setFilterError(null);
      setFilterDraft((draft) => ({ ...draft, kind }));
      setActivePixelOperation({ kind, mode });
    },
    [document, selectedLayer],
  );

  const applyCanvasSize = useCallback(() => {
    if (!document || parsedCanvasSize.error) return;
