import type { CommandRegistry, EditorCommand } from './commandTypes.js';

export function createCommandRegistry(commands: readonly EditorCommand[]): CommandRegistry {
  const registry = new Map<string, EditorCommand>();
  for (const command of commands) {
    if (registry.has(command.id)) throw new Error(`Duplicate command id: ${command.id}`);
    registry.set(command.id, command);
  }
  return registry;
}

export function executeCommand(registry: CommandRegistry, id: string): boolean {
  const command = registry.get(id);
  if (!command?.enabled) return false;
  command.execute();
  return true;
}

import type { CommandMenu, CommandSubmenuId } from './commandTypes.js';

export interface CommandSubmenuDefinition {
  readonly id: CommandSubmenuId;
  readonly menu: CommandMenu;
  readonly parentId?: CommandSubmenuId;
  readonly label: string;
  readonly order: number;
  readonly separatorBefore?: boolean;
}

export interface MenuDefinition {
  readonly id: CommandMenu;
  readonly label: string;
}

export const MENU_DEFINITIONS: readonly MenuDefinition[] = [
  { id: 'file', label: 'File' },
  { id: 'edit', label: 'Edit' },
  { id: 'image', label: 'Image' },
  { id: 'layer', label: 'Layer' },
  { id: 'type', label: 'Type' },
  { id: 'select', label: 'Select' },
  { id: 'filter', label: 'Filter' },
  { id: 'view', label: 'View' },
  { id: 'window', label: 'Window' },
  { id: 'help', label: 'Help' },
];

export const COMMAND_SUBMENU_DEFINITIONS: readonly CommandSubmenuDefinition[] = [
  { id: 'image.adjustments', menu: 'image', label: 'Adjustments', order: 100 },
  { id: 'filter.blur', menu: 'filter', label: 'Blur', order: 100, separatorBefore: true },
  {
    id: 'layer.new-adjustment',
    menu: 'layer',
    label: 'New Adjustment Layer',
    order: 120,
    separatorBefore: true,
  },
];

      execute: () => setViewport((view) => ({ ...view, zoom: 1 })),
    },
    {
