/**
 * Clone stamp tool implementation for FreetoShop.
 *
 * Samples pixels from a source layer and writes them to a destination layer using
 * the existing brush rasterization pipeline. Supports aligned and unaligned modes,
 * transformed layers, and selection clipping.
 */

import type {
  BrushPoint,
  PixelLayer,
  PixelPatch,
  SelectionMask,
  LayerTransform,
} from '@freetoshop/core-document';
import { TiledPixelStore } from '@freetoshop/pixel-storage';

export interface CloneSource {
  /** Document-space x coordinate of the clone source origin. */
  readonly sourceX: number;
  /** Document-space y coordinate of the clone source origin. */
  readonly sourceY: number;
  /** When aligned, the offset from source to destination. When null, source = destination. */
  readonly offset: { x: number; y: number } | null;
  /** Whether the source-to-destination offset is preserved across the stroke. */
  readonly aligned: boolean;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly mode: 'source-over' | 'erase';
  readonly source: CloneSource;
}

interface LocalDab {
  x: number;
  y: number;
  pressure: number;
}

/**
 * Builds interpolated dabs from sparse pointer points.
 * Reuses the same spacing logic as paintStroke for consistency.
 */
function buildDabs(points: readonly BrushPoint[], radius: number): LocalDab[] {
  const dabs: LocalDab[] = [];
  const first = points[0];
  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });

  const spacing = Math.max(0.25, radius * 0.5);
  for (let i = 1; i < points.length; i++) {
    const start = points[i - 1];
    const end = points[i];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step++) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }
  return dabs;
}

/**
 * Paints a clone stamp stroke. Samples from source layer and writes to destination layer.
 *
 * In aligned mode, the offset between source and destination is preserved across the stroke.
 * In unaligned mode, each dab re-samples from the original source point.
 *
 * Both layers can have different world transforms, allowing transformed layers to be cloned correctly.
 */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform: LayerTransform = destinationLayer.transform,
  sourceWorldTransform: LayerTransform = sourceLayer.transform,
): PixelPatch {
  const { size, hardness, opacity, mode, source } = options;

  // Validate inputs
  if (points.length === 0) {
    throw new RangeError('Stroke must contain at least one point');
  }
  if (size <= 0) {
    throw new RangeError('Clone stamp size must be greater than 0');
  }
  if (hardness < 0 || hardness > 1) {
    throw new RangeError('Clone stamp hardness must be between 0 and 1');
  }
  if (opacity < 0 || opacity > 1) {
    throw new RangeError('Clone stamp opacity must be between 0 and 1');
  }

  const radius = size / 2;

  // Build interpolated dabs
  const dabs = buildDabs(points, radius);

  // Calculate source-to-destination offset for aligned mode
  // In aligned mode, we track the offset from the initial source point to the first destination point
  let alignedOffset: { x: number; y: number } | null = null;
  if (source.aligned && source.offset !== null) {
    alignedOffset = source.offset;
  } else if (source.aligned) {
    // Calculate offset from first dab to source point
    alignedOffset = {
      x: dabs[0].x - source.sourceX,
      y: dabs[0].y - source.sourceY,
    };
  }

  // For each dab, compute the source sample point
  // Destination document coordinates are the dab coordinates (already in document space)
  // Source document coordinates depend on aligned/unaligned mode

  // We need to transform between document space and layer-local space for both layers
  const destInverse = invertTransform(destinationWorldTransform);
  const srcInverse = invertTransform(sourceWorldTransform);

  // Stroke bounds (for efficient tile reads)
  let strokeBounds: { left: number; top: number; right: number; bottom: number } | null = null;

  for (const dab of dabs) {
    // Compute destination point in document space (it's the dab point itself)
    const destDocX = dab.x;
    const destDocY = dab.y;

    // Compute source point in document space
    let srcDocX: number;
    let srcDocY: number;

    if (source.aligned && alignedOffset !== null) {
      // Aligned: preserve offset
      srcDocX = destDocX + alignedOffset.x;
      srcDocY = destDocY + alignedOffset.y;
    } else if (!source.aligned && source.offset !== null) {
      // Unaligned with offset: always use source point + offset
      srcDocX = source.sourceX + source.offset.x;
      srcDocY = source.sourceY + source.offset.y;
    } else if (!source.aligned) {
      // Unaligned without offset: always use source point
      srcDocX = source.sourceX;
      srcDocY = source.sourceY;
    } else {
      // Aligned without offset: source = destination (copy same location)
      srcDocX = destDocX;
      srcDocY = destDocY;
    }

    // Transform to layer-local coordinates
    const destLocal = transformPoint(destInverse, destDocX, destDocY);
    const srcLocal = transformPoint(srcInverse, srcDocX, srcDocY);

    // Accumulate bounds for destination layer
    if (!strokeBounds) {
      strokeBounds = {
        left: Math.floor(destLocal.x - radius),
        top: Math.floor(destLocal.y - radius),
        right: Math.ceil(destLocal.x + radius),
        bottom: Math.ceil(destLocal.y + radius),
      };
    } else {
      strokeBounds.left = Math.min(strokeBounds.left, Math.floor(destLocal.x - radius));
      strokeBounds.top = Math.min(strokeBounds.top, Math.floor(destLocal.y - radius));
      strokeBounds.right = Math.max(strokeBounds.right, Math.ceil(destLocal.x + radius));
      strokeBounds.bottom = Math.max(strokeBounds.bottom, Math.ceil(destLocal.y + radius));
    }
  }

  if (!strokeBounds) {
    return emptyPatch();
  }

  // Clip bounds to destination layer
  strokeBounds.left = Math.max(0, strokeBounds.left);
  strokeBounds.top = Math.max(0, strokeBounds.top);
  strokeBounds.right = Math.min(destinationLayer.width - 1, strokeBounds.right);
  strokeBounds.bottom = Math.min(destinationLayer.height - 1, strokeBounds.bottom);

  if (strokeBounds.left > strokeBounds.right || strokeBounds.top > strokeBounds.bottom) {
    return emptyPatch();
  }

  // Read destination tiles
  const regionLeft = strokeBounds.left;
  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;

  const destPixels = destinationLayer.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });

  // Selection handling
  let selectionBuffer: Uint8ClampedArray | null = null;
  let selectionRegion: { left: number; top: number; right: number; bottom: number } | null = null;

  if (selection) {
    selectionRegion = {
      left: Math.max(0, strokeBounds.left - Math.ceil(radius)),
      top: Math.max(0, strokeBounds.top - Math.ceil(radius)),
      right: Math.min(selection.width - 1, strokeBounds.right + Math.ceil(radius)),
      bottom: Math.min(selection.height - 1, strokeBounds.bottom + Math.ceil(radius)),
    };
    if (selectionRegion.left <= selectionRegion.right && selectionRegion.top <= selectionRegion.bottom) {
      selectionBuffer = selection.coverageStore.read({
        x: selectionRegion.left,
        y: selectionRegion.top,
        width: selectionRegion.right - selectionRegion.left + 1,
        height: selectionRegion.bottom - selectionRegion.top + 1,
      });
    }
  }

  // Process each dab
  let changedBounds: { left: number; top: number; right: number; bottom: number } | null = null;

  for (let i = 0; i < dabs.length; i++) {
    const dab = dabs[i];

    // Compute destination point in document space
    const destDocX = dab.x;
    const destDocY = dab.y;

    // Compute source point in document space
    let srcDocX: number;
    let srcDocY: number;

    if (source.aligned && alignedOffset !== null) {
      srcDocX = destDocX + alignedOffset.x;
      srcDocY = destDocY + alignedOffset.y;
    } else if (!source.aligned && source.offset !== null) {
      srcDocX = source.sourceX + source.offset.x;
      srcDocY = source.sourceY + source.offset.y;
    } else if (!source.aligned) {
      srcDocX = source.sourceX;
      srcDocY = source.sourceY;
    } else {
      srcDocX = destDocX;
      srcDocY = destDocY;
    }

    // Transform to layer-local coordinates
    const destLocal = transformPoint(destInverse, destDocX, destDocY);
    const srcLocal = transformPoint(srcInverse, srcDocX, srcDocY);

    // Check source bounds
    if (srcLocal.x < 0 || srcLocal.y < 0 || srcLocal.x >= sourceLayer.width || srcLocal.y >= sourceLayer.height) {
      continue;
    }

    // For each pixel in the dab's affected region
    const startX = Math.max(regionLeft, Math.floor(destLocal.x - radius));
    const startY = Math.max(regionTop, Math.floor(destLocal.y - radius));
    const endX = Math.min(regionLeft + regionWidth - 1, Math.ceil(destLocal.x + radius));
    const endY = Math.min(regionTop + regionHeight - 1, Math.ceil(destLocal.y + radius));

    for (let y = startY; y <= endY; y++) {
      for (let x = startX; x <= endX; x++) {
        // Document-space position of this pixel
        const docPoint = transformPoint(destinationWorldTransform, x, y);

        // Distance from dab center
        const dx = docPoint.x - destDocX;
        const dy = docPoint.y - destDocY;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance > radius) continue;

        // Hardness falloff
        const falloff = hardness >= 1
          ? 1
          : distance <= radius * hardness
            ? 1
            : 1 - (distance - radius * hardness) / (radius - radius * hardness);

        // Selection coverage
        let selectionCoverage = 1;
        if (selectionBuffer && selectionRegion) {
          const selX = Math.floor(docPoint.x);
          const selY = Math.floor(docPoint.y);
          if (selX >= selectionRegion.left && selX <= selectionRegion.right &&
              selY >= selectionRegion.top && selY <= selectionRegion.bottom) {
            const localX = selX - selectionRegion.left;
            const localY = selY - selectionRegion.top;
            selectionCoverage = selectionBuffer[localY * (selectionRegion.right - selectionRegion.left + 1) + localX] / 255;
          } else {
            selectionCoverage = 0;
          }
        }

        const strength = falloff * opacity * dab.pressure * selectionCoverage;
        if (strength <= 0) continue;

        // Sample source pixel
        const srcPixel = sourceLayer.pixelStore.read({
          x: Math.round(srcLocal.x),
          y: Math.round(srcLocal.y),
          width: 1,
          height: 1,
        });

        // Write to destination using source-over compositing (or erase)
        const destOffset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
        if (mode === 'erase') {
          destPixels[destOffset + 3] = Math.round((destPixels[destOffset + 3] ?? 0) * (1 - strength));
        } else {
          // Source-over compositing
          const srcAlpha = (srcPixel[3] ?? 0) / 255 * strength;
          const destAlpha = (destPixels[destOffset + 3] ?? 0) / 255;
          const outAlpha = srcAlpha + destAlpha * (1 - srcAlpha);

          if (outAlpha > 0) {
            for (let c = 0; c < 3; c++) {
              const src = srcPixel[c] ?? 0;
              const dest = destPixels[destOffset + c] ?? 0;
              destPixels[destOffset + c] = Math.round((src * srcAlpha + dest * destAlpha * (1 - srcAlpha)) / outAlpha);
            }
            destPixels[destOffset + 3] = Math.round(outAlpha * 255);
          }
        }

        // Track changed region
        if (!changedBounds) {
          changedBounds = { left: x, top: y, right: x, bottom: y };
        } else {
          changedBounds.left = Math.min(changedBounds.left, x);
          changedBounds.top = Math.min(changedBounds.top, y);
          changedBounds.right = Math.max(changedBounds.right, x);
          changedBounds.bottom = Math.max(changedBounds.bottom, y);
        }
      }
    }
  }

  if (!changedBounds) {
    return emptyPatch();
  }

  // Create patch from changed region
  const patchLeft = Math.max(regionLeft, changedBounds.left);
  const patchTop = Math.max(regionTop, changedBounds.top);
  const patchRight = Math.min(regionLeft + regionWidth - 1, changedBounds.right);
  const patchBottom = Math.min(regionTop + regionHeight - 1, changedBounds.bottom);

  const patchWidth = patchRight - patchLeft + 1;
  const patchHeight = patchBottom - patchTop + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  for (let y = patchTop; y <= patchBottom; y++) {
    for (let x = patchLeft; x <= patchRight; x++) {
      const srcOffset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = destPixels[srcOffset];
      patchPixels[dstOffset + 1] = destPixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = destPixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = destPixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

function invertTransform(transform: LayerTransform): LayerTransform {
  const det = transform.a * transform.d - transform.b * transform.c;
  if (det === 0) {
    throw new RangeError('Transform is not invertible');
  }
  return {
    a: transform.d / det,
    b: -transform.b / det,
    c: -transform.c / det,
    d: transform.a / det,
    e: (transform.c * transform.f - transform.d * transform.e) / det,
    f: (transform.b * transform.e - transform.a * transform.f) / det,
  };
}

function transformPoint(transform: LayerTransform, x: number, y: number): { x: number; y: number } {
  return {
    x: transform.a * x + transform.c * y + transform.e,
    y: transform.b * x + transform.d * y + transform.f,
  };
}

function emptyPatch(): PixelPatch {
  return {
    x: 0,
    y: 0,
    width: 0,
    height: 0,
    pixels: new Uint8ClampedArray(0),
  };
}

